/**
 * Deinterlacing what the media element shows, on the GPU.
 *
 * A transport stream off the air is interlaced, and the video keeps it that
 * way: the browser decodes each pair of fields into one frame, so what a
 * `<video>` puts on screen is combed wherever anything moved. Nothing in the
 * platform will undo that, and doing it on the CPU at 1080i is out of the
 * question, so this takes the frames the element presents and filters them in
 * WebGL, on a canvas laid over the element.
 *
 * The filter is supplied by the separate @mpeg2toh264/yadif package because it
 * is derived from FFmpeg and licensed differently. Everything here
 * is the machinery around it: three frames' worth of textures, a program, and
 * frame callbacks (Firefox's moz counters, native rVFC elsewhere) to say when
 * a frame is worth uploading.
 *
 * Frames are filtered one behind the element. yadif wants the frame either
 * side of the one it is working on, and the only way to hold the next one is
 * to wait for it, so the canvas is one frame -- around 33 ms -- behind the
 * audio. That is well inside what a viewer can tell, and the alternative is a
 * filter with half its motion measurements missing.
 *
 * With `film` on, 2:3 pulldown is detected on the GPU (see film-shader.ts):
 * each frame is put back together into the film frame it came from, the
 * repeated one in every five is dropped, and the rest are shown at 24 a
 * second, evenly spaced.
 *
 * Pictures can instead be pushed already decoded, with their presentation
 * times, through `decodedVideo`. The element then only plays the sound and
 * keeps the time: each picture is filtered as soon as its successor is in
 * hand, and each field is shown at the refresh its own time falls in.
 */
import {
  destroyDebugRenderState,
  drawText,
  initDebugRenderState,
  type DebugRenderState,
} from "./debug.js";
import { YADIF_FRAGMENT_SHADER, YADIF_UNIFORMS } from "./shader.js";
import { FilmDetector, NO_PHASE, type Phase } from "./film-detect.js";
import {
  checkPicture,
  PictureConverter,
  type DecodedPicture,
  type DecodedVideoInput,
} from "./decoded-video.js";
import { MediaClock } from "./media-clock.js";
import { PictureWatch } from "./picture-watch.js";
import {
  FIELD_METRICS,
  FILM_DUPLICATE_PHASE,
  FILM_LOCK_FRAMES,
} from "./film-shader.js";
import {
  VideoFrames,
  supportsVideoFrames,
  type FrameMetadata,
} from "./video-frame.js";
import type {
  WorkerCommand,
  WorkerNotification,
  WorkerRenderingOptions,
  WorkerVideoState,
} from "./worker-protocol.js";

let bundledWorkerURL: string | URL | null = null;

/** @internal Receive the bundled Worker's URL from the public entry point. */
export function setBundledWorkerURL(url: string | URL): void {
  bundledWorkerURL = url;
}

/** How far the presentation time may jump before the held frames are stale. */
const CONTINUOUS_SECONDS = 0.5;

/** pprev, prev, cur and next: the filter reads three, the detection four. */
const HISTORY = 4;

const FIELD_QUEUE_LENGTH = 5;

/**
 * One output remains reserved while its picture is represented by the canvas,
 * so `capture()` can reproduce it without preserving the drawing buffer.
 */
const OUTPUT_POOL_LENGTH = FIELD_QUEUE_LENGTH + 1;

/** How often the filter says how it is getting on, in milliseconds. */
const STATS_INTERVAL_MS = 1000;

/** What a frame period has to be within to be believed, in milliseconds. */
const MIN_PERIOD_MS = 4;
const MAX_PERIOD_MS = 200;

/** How much of each measurement the smoothed frame period takes. */
const PERIOD_SMOOTHING = 0.25;

/** The screen's refresh interval until animation frames have said otherwise. */
const DEFAULT_REFRESH_MS = 1000 / 60;

const VERTEX_SHADER = `#version 300 es
void main() {
  // One triangle over the whole viewport, from the vertex index alone. There
  // is no geometry here worth a buffer: every pixel is the fragment shader's.
  vec2 corner = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
  gl_Position = vec4(corner * 2.0 - 1.0, 0.0, 1.0);
}
`;

/** A measurement under this fraction of the period replaces it outright. */
const PERIOD_SHORTER = 0.75;

/**
 * How much of the gap between the schedule and the clock each picture makes
 * up, and the most one picture is moved by, in milliseconds. See #schedule.
 * (otya: drift-corrected chaining keeps chained pictures on the clock without
 * any of them ever moving across a refresh.)
 */
const DRIFT_GAIN = 0.1;
const DRIFT_STEP_MS = 1;

/**
 * Number of consecutive pictures that must miss the phase the schedule
 * allows for before the schedule moves that phase. 60 is two seconds of video
 * frames. While the frame period drifts past the refresh, one frame in three
 * still arrives at the old phase, so the window never completes then.
 */
const SCHEDULE_WINDOW = 60;

/** How much of each animation frame's error the refresh grid takes. (otya) */
const GRID_PERIOD_GAIN = 0.02;
const GRID_PHASE_GAIN = 0.1;

/** Hysteresis around the half-refresh boundary, in milliseconds. (otya) */
const PRESENT_HYSTERESIS_MS = 1;

/**
 * How far from the moment a frame was taken in hand its reported display time
 * may be and still be believed, in whichever of the refresh and frame periods
 * is longer. A report that cannot describe this frame is not one to schedule
 * from: WebKit has reported times already past, and a translation across two
 * clocks is only as good as the origin the other side stamped.
 */
const DISPLAY_TIME_REACH = 4;

/**
 * Frames after the cadence was last held during which a field may still be
 * woven with a matching field of a neighbouring frame. A cut after pulldown
 * restarts the cycle, and confirming the new cycle takes FILM_LOCK_FRAMES
 * frames that are film anyway. On a broadcast episode these gaps were mostly
 * under a second, and almost every moving field in them had a partner. Three
 * seconds covers them without trusting partners in video, where a block that
 * barely moves can look like it has one.
 */
const FILM_HOLD_FRAMES = 90;

/**
 * How far ahead of the refresh being filled a decoded picture is filtered, in
 * refreshes of wall time. More than one, so that a late animation frame still
 * finds its field filtered. Less than a picture at normal speed, so that a B
 * picture pushed before its own time is in hand before the anchor shown after
 * it is taken in.
 */
const LOOKAHEAD_REFRESHES = 1.5;

/**
 * Decoded pictures held before being taken in, per unit of playback rate.
 * About 0.8 s of 29.97 pictures: well above what the producer sends ahead.
 */
const PICTURE_QUEUE = 24;

/** How far two decoded timestamps may disagree and still be the same moment, in seconds. */
const TIMESTAMP_TOLERANCE = 0.001;

/** Broadcast frames in a pulldown cycle, and the film frames they hold. */
const PULLDOWN_FRAMES = 5;
const FILM_FRAMES = 4;

/**
 * How long after its frame arrives a film frame of each phase is shown, in
 * frame periods, so that the film frames come out 1.25 periods apart. Phase
 * 2 is whole only once the frame after it has arrived, so it goes up at
 * once and the others are held back to match. Phase 1 is the repeat.
 * (otya)
 */
const FILM_LEAD: Record<number, number> = {
  2: 0,
  3: 0.25,
  4: 0.5,
  5: 0.75,
};

/** The shared scan of a decoded picture. */
function decodedScan(picture: HeldPicture): Scan {
  return DECODED_SCANS[
    (picture.interlaced ? 2 : 0) + (picture.topFieldFirst ? 1 : 0)
  ]!;
}

/**
 * Putting a picture that has already been filtered onto the canvas.
 *
 * Both the texture it reads and the canvas it writes are held the way a
 * framebuffer is, rows from the bottom, so there is nothing to turn over
 * between them and the copy is texel for texel.
 */
const BLIT_FRAGMENT_SHADER = `#version 300 es
precision highp float;
uniform sampler2D uField;
uniform bool uFlip;
out vec4 fragColor;
void main() {
  ivec2 position = ivec2(gl_FragCoord.xy);
  if (uFlip) position.y = textureSize(uField, 0).y - 1 - position.y;
  fragColor = texelFetch(uField, position, 0);
}
`;

/** A filtered picture waiting for the moment it stands for. */
interface Ready {
  /** Which of the output textures holds it. */
  slot: number;
  /** When it belongs on the screen, on `performance.now()`'s clock. */
  at: number;
  duration: number;
  /** Which schedule chained it (otya): a cadence change restarts the chain. */
  cadence: Cadence;
  /** GPU pulldown phase, field number, or 0 for ordinary frames. */
  phase: number;
  droppedBefore: number;
}

type Cadence = "frame" | "field" | "film";

/** What the renderer keeps of a decoded picture once its samples are in a texture. */
interface HeldPicture {
  timestamp: number;
  duration: number;
  interlaced: boolean;
  topFieldFirst: boolean;
  repeatFirstField: boolean;
}

/** A decoded picture's filtered field or frame waiting for its media time. */
interface DecodedOutput {
  slot: number;
  /** When it belongs on the screen, in media seconds. */
  time: number;
  /** The timestamp of the picture it is made from. */
  picture: number;
  /**
   * When that picture stops being the one to show: when the first output of
   * the picture after it is due, or its own end where no successor is known.
   */
  end: number;
  /** Whether it is the first output of that picture, which is what a paused element shows. */
  start: boolean;
  scan: Scan;
}

/** The scan of each kind of decoded picture, shared so that outputs allocate none. */
const DECODED_SCANS: readonly Scan[] = [
  { interlaced: false, topFieldFirst: false },
  { interlaced: false, topFieldFirst: true },
  { interlaced: true, topFieldFirst: false },
  { interlaced: true, topFieldFirst: true },
];

/** Callback metadata describing one presented frame to take in. */
interface FrameObservation {
  mediaTime: number;
  presentedFrames: number;
  /**
   * The display time reported by requestVideoFrameCallback(), which anchors
   * the presentation schedule (otya). Acquisition and rendering may use
   * different performance clocks, so carry `timeOrigin` with it and convert
   * to the renderer's clock before scheduling. On Firefox, VideoFrames
   * supplies the time of the poll that delivered the frame instead.
   */
  expectedDisplayTime: number;
  /** The performance.timeOrigin against which `expectedDisplayTime` was measured. */
  timeOrigin: number;
  width: number;
  height: number;
  /**
   * Set on Firefox when the frame comes through VideoFrames. mediaTime there
   * is the coarse media clock, which cannot identify a frame or time its
   * fields. Use presentedFrames and this instead.
   */
  mozTiming?: { periodMs: number; discontinuity: boolean };
}

/** The draw path that produced the picture still represented by the canvas. */
type PresentedPicture =
  | { kind: "texture"; texture: WebGLTexture; flip: boolean }
  | { kind: "yadif"; flush: boolean; second: boolean };

/**
 * How the filter is getting on, and where it is being let down.
 *
 * A deinterlacer is only as good as the frames it is given. yadif reads the
 * frame either side of the one it is filtering, and every count here that is
 * not `filtered` is a way of not having them: a frame the callback never saw
 * leaves the two neighbours two frames apart, and one filtered against a copy
 * of itself has no motion to measure at all. Both show up as combing that
 * comes and goes, which is worth being able to point at rather than guess at.
 */
export interface DeinterlaceStats {
  /** Frames filtered with a real frame on either side: the good case. */
  filtered: number;
  /**
   * Frames the element presented that the filter never saw, counted from the
   * gaps in `presentedFrames`. The neighbours of the frames either side of a
   * gap are further apart in time than the filter believes, so its idea of
   * what moved is wrong. A page that sees this climbing is asking the filter
   * to keep up with more than it can.
   *
   * Firefox does not report this count. With main-thread rendering the gaps
   * are taken from the time between new pictures. A frame whose pixels equal
   * the previous frame's cannot be told apart from a missed one, so a still
   * scene raises this count although nothing is wrong. With Worker rendering
   * the gaps are those in `mozPaintedFrames`.
   *
   * With decoded pictures, the pictures dropped because their time had
   * passed before they could be taken in, none of them shown. Pictures that
   * ended before the place playback last started from are not counted: they
   * were never due.
   */
  missed: number;
  /**
   * Frames the browser decoded and threw away without presenting, as the
   * element itself counts them. This is the machine being behind rather than
   * this filter: it happens with the deinterlacer off as well.
   */
  dropped: number;
  /**
   * Frames filtered with a copy of themselves standing in for a neighbour,
   * which is the start of a stream, the frame a seek lands on, and the last
   * frame before playback stops. Expected in ones and twos; a stream of them
   * means the held frames keep being thrown away.
   */
  degraded: number;
  /** Times the held frames were dropped as stale: seeks, and stream changes. */
  discontinuities: number;
  /**
   * Times the schedule was restarted from the clock instead of following on
   * from the last picture: a seek, a stall, a cadence change, or a missed
   * frame. Climbing during steady playback means the cadence is not holding.
   * (otya) With decoded pictures, times the media clock started again from
   * `currentTime`: after a seek, a pause, a rate change or a stall, or on a
   * reading too far from it.
   */
  resynced: number;
  /**
   * Fields skipped because their display time passed or disagreed with the
   * presentation clock. With decoded pictures, every field or frame filtered
   * or due and never shown, including those a rate above the refresh skips,
   * but not those from before the place playback last started from.
   */
  late: number;
  /**
   * Times the presentation queue was reset because its scheduled lead exceeded
   * the useful display window. With decoded pictures, pictures dropped
   * because more were pushed than are held.
   */
  queueResetted: number;
  /**
   * Frames presented per second over the last report. With decoded pictures,
   * pictures taken in per second.
   */
  fps: number;
  /**
   * Average rendering-thread time per input frame spent uploading, filtering
   * and presenting during the last report. Excludes GPU execution time and,
   * when rendering in a Worker, time spent on the main thread. On Firefox
   * with main-thread rendering it also excludes the upload, which happens
   * once per refresh while polling for new pictures, not once per frame.
   */
  frameMs: number;
  /**
   * The largest number of pictures queued during the last reporting interval,
   * across both the field-rate and film scheduling paths. With decoded
   * pictures, the largest number pushed and not yet taken in.
   */
  maxQueuedFields: number;
  /**
   * Pictures actually copied to the canvas per second: with decoded pictures,
   * fields, film frames or frames, as the mode shows them.
   */
  outputFps: number;
  /**
   * GPU processing time, supported only in Chrome. On ANGLE's Metal backend
   * it spans command buffers rather than the work in them, so it overstates
   * anything split into many small passes; a change is best judged by its
   * direction here and by a synchronous readback in isolation.
   */
  gpuMs: number | undefined;
  /** Whether 2:3 pulldown has been detected and the frames are shown at 24p. */
  film: boolean;
  /**
   * Whether the two fields of each frame were recently found to be one
   * instant, as in 30p material or film carried by repeated whole frames.
   * This is the detection's last verdict read back from the GPU. While it
   * holds, both fields of a frame are drawn as the same whole picture instead
   * of two interpolated ones, except while a pulldown cadence is held and on
   * the frame after a gap. Only evaluated while `film` is on.
   */
  oneInstant: boolean;
  /**
   * Frames filtered with no cadence held, in which a field could be woven
   * with a matching field of a neighbouring frame. These are the frames
   * shortly after a cadence is lost. Weaving because of the `oneInstant`
   * verdict is not counted. Blocks without a matching partner are still
   * interpolated, so on video inside this window the count includes frames
   * in which nothing was woven.
   */
  matched: number;
  /**
   * Why requested film reconstruction is currently unavailable, or null
   * while healthy. The requesting option (`film`) stays as the
   * caller set it -- intent is preserved -- while pictures continue through
   * plain YADIF. Cleared on the next retry (start, scan change, resize, or
   * re-setting the option); a repeated failure notifies again as a new
   * episode. Always null when film reconstruction is not requested.
   */
  filmError?: string | null;
}

export interface DeinterlacerOptions {
  /** Rendering target, defaulting to `main`; `auto` prefers the bundled Worker and falls back to the main thread if initialization fails. */
  rendering?: "auto" | "worker" | "main";
  /** The module Worker's URL, defaulting to the file bundled with the package. */
  workerUrl?: string | URL;
  /**
   * Whether to show a picture for every field rather than for every frame.
   *
   * Interlaced video carries two moments in each frame, and one output frame
   * per input frame throws the second one away: motion that was captured
   * fifty or sixty times a second is shown twenty-five or thirty. With this
   * on, each frame is filtered twice -- once keeping the field that came
   * first and once keeping the other -- and the second picture is put up half
   * a frame after the first, which is the moment it was taken at. Motion is
   * as smooth as the broadcast was, at twice the filtering.
   *
   * It needs a display that can show them: at 59.94 fields a second there is
   * one refresh of a 60 Hz screen for each, and nothing to spare.
   *
   * With `spatialCheck`, this is which of yadif's four modes runs: off/on is
   * `send_frame`, on/on is `send_field`, and the two with `spatialCheck` off
   * are the `nospatial` pair.
   */
  doubleRate?: boolean;
  /**
   * Whether to let the local vertical range widen what the temporal check
   * allows. This is yadif's default and its `nospatial` mode turns it off.
   */
  spatialCheck?: boolean;
  /**
   * Called about once a second while frames are arriving, and not at all while
   * nothing is playing -- there is nothing to say about a filter that is not
   * being asked for anything.
   */
  onStats?(stats: DeinterlaceStats): void;
  /**
   * Whether to detect 2:3 pulldown and show film at 24 frames a second.
   * Frames that are not film are filtered as usual. Needs
   * `EXT_color_buffer_float`.
   */
  film?: boolean;
  /**
   * Called when a rendering resource fails after construction: a GPU film detector that throws mid-stream,
   * a Worker that died twice, or a lost WebGL context.
   * The same message is dispatched as a `failure` event.
   * This option lets callers install the handler alongside `onStats`.
   */
  onFailure?(message: string): void;
  /**
   * Whether to draw the pulldown detection over the picture while `film` is enabled.
   */
  debug?: boolean;
}

/** Field information supplied by a player or another video source. */
export interface Scan {
  interlaced: boolean;
  topFieldFirst: boolean;
}

export interface VideoState {
  start: number;
  codedSize?: { width: number; height: number };
  scan?: Scan;
}

export interface DeinterlacerEventMap {
  stats: CustomEvent<DeinterlaceStats>;
  /** A rendering resource failed after construction; detail is the reason. */
  failure: CustomEvent<string>;
}

/** Whether this browser has the two things the deinterlacer is built on. */
export function supportsDeinterlace(): boolean {
  return supportsVideoFrames() && typeof WebGL2RenderingContext !== "undefined";
}

type RenderTarget = {
  texture: WebGLTexture;
  framebuffer: WebGLFramebuffer;
};

interface EXT_disjoint_timer_query_webgl2 {
  readonly QUERY_COUNTER_BITS_EXT: 0x8864;
  readonly TIME_ELAPSED_EXT: 0x88bf;
  readonly TIMESTAMP_EXT: 0x8e28;
  readonly GPU_DISJOINT_EXT: 0x8fbb;

  queryCounterEXT(query: WebGLQuery, target: GLenum): void;
}

/**
 * Somewhere animation frames come from.
 *
 * A `Window` is one, and so is the Worker host below. Which one is in use is
 * not fixed for the lifetime of a deinterlacer: a document picture-in-picture
 * window can adopt the element and its canvas, and from then on it is that
 * window that composites them. The object itself is the identity a pending
 * request is cancelled against, so it has to be the same object each time the
 * same source is asked for.
 */
interface AnimationFrames {
  requestAnimationFrame(callback: FrameRequestCallback): number;
  cancelAnimationFrame(handle: number): void;
}

/**
 * The frames this module's own realm hands out, for when the canvas is in no
 * document that has a window: a detached element, or a picture-in-picture
 * window that has since closed.
 */
const moduleAnimationFrames: AnimationFrames = {
  requestAnimationFrame: (callback) => requestAnimationFrame(callback),
  cancelAnimationFrame: (handle) => cancelAnimationFrame(handle),
};

/** An outstanding request, with the source that must be used to cancel it. */
interface AnimationRequest {
  frames: AnimationFrames;
  handle: number;
}

/** Internal host supplied by the Worker entry point to build the same rendering engine. */
interface ExternalRenderingHost extends AnimationFrames {
  canvas: OffscreenCanvas;
  onFailure(message: string): void;
  onVisibility(visible: boolean): void;
}

/** The newest frame and its observed state, owned by the page while awaiting an acknowledgement. */
interface PendingWorkerFrame {
  id: number;
  frame: VideoFrame;
  now: number;
  metadata: FrameObservation;
  video: WorkerVideoState;
}

/**
 * Puts a deinterlaced copy of a `<video>` over the top of it.
 *
 * ```ts
 * const deinterlacer = new Deinterlacer(video);
 * deinterlacer.start();
 * ```
 *
 * `start()` wraps the element in a positioned `<div>` and adds a canvas over
 * it. The canvas takes no pointer events, so anything the page put on the
 * element still works, but it does cover the element's own controls; a page
 * that wants controls with this on has to draw them itself. `stop()` hides the
 * canvas again, which is all it takes to compare the two.
 *
 * While frames are arriving, the current counters are also dispatched as a
 * `stats` event about once a second. The optional `onStats` callback receives
 * the same snapshot for callers that prefer a constructor option.
 */
export class Deinterlacer extends EventTarget {
  /**
   * Receive decoded pictures with their presentation times. From the first
   * push on they are the only pictures shown, and the element is only the
   * clock they are shown by.
   */
  readonly decodedVideo: DecodedVideoInput;
  readonly #renderCanvas: HTMLCanvasElement | OffscreenCanvas;
  #displayCanvas: HTMLCanvasElement;

  readonly #video: HTMLVideoElement;
  readonly #videoFrames: VideoFrames;
  /** Finds Firefox's new pictures for the main-thread renderer. */
  readonly #pictures: PictureWatch | null;
  /** The take holding the picture of the frame being ingested, if any. */
  #stagedPicture: number | null = null;
  readonly #gl: WebGL2RenderingContext;
  /** The pulldown detection, built only while the `film` option needs it. */
  #detector: FilmDetector | null = null;
  readonly #program: WebGLProgram;
  readonly #location: Record<
    keyof typeof YADIF_UNIFORMS,
    WebGLUniformLocation | null
  >;
  /** The program that copies a filtered picture onto the canvas. */
  readonly #blit: WebGLProgram;
  readonly #blitField: WebGLUniformLocation | null;
  readonly #blitFlip: WebGLUniformLocation | null;
  #textures: WebGLTexture[] = [];
  /** Somewhere to filter a field into, and to read it back out of. */
  #outputs: RenderTarget[] = [];
  /** Which output slot was written last; the next one follows round the ring. */
  #outputHead = OUTPUT_POOL_LENGTH - 1;
  /** The draw path currently shown on the canvas, retained for snapshots. */
  #presentedPicture: PresentedPicture | null = null;
  /** Filtered fields waiting for their moment, oldest first. */
  #queue: Ready[] = [];
  /** The requestAnimationFrame() loop that puts them up, which is all that draws on the canvas. */
  #loopRequest: AnimationRequest | null = null;
  #lastLoopAt = 0;
  /** Deliver captured pictures on the page's refresh during faster playback. */
  #captureRequest: AnimationRequest | null = null;
  /** The document the owner-change listener is on, if any. */
  #ownerDocument: Document | null = null;
  readonly #ownerChanges: MutationObserver | null;
  /** The gap between animation frames: as near as the page gets to the screen. */
  #refreshMs = DEFAULT_REFRESH_MS;
  /** Where the refresh grid fitted to the animation frames stands. (otya) */
  #gridAt = 0;
  /** How far ahead of its animation frame the last picture shown stood. (otya) */
  #shownAhead = 0;
  #shownAt = 0;
  #droppedBefore = 0;
  /** The last picture chained onto the schedule; a break restarts it. (otya) */
  #lastScheduled: Ready | null = null;
  /** The lateness the schedule holds on purpose, in refreshes. See #schedule. */
  #scheduleLag = 0;
  /** Pictures in a row that arrived off the phase the lag stands for, all on one side of it. */
  #offPhase = 0;
  /** Of those, the phase closest to the lag's phase, in refreshes. */
  #offPhaseNearest = 0;

  /**
   * Drop the presentation queue and restart the schedule from the clock.
   * Every schedule restart goes through here (otya nulls #lastScheduled at
   * each queue clear): the old chain's clock no longer applies, so keeping
   * it would either count a phantom resync or pop freshly queued pictures
   * as late. Restart accounting for cadence changes lives in #schedule.
   */
  #dropQueue(): void {
    this.#queue.length = 0;
    this.#decodedQueue.length = 0;
    this.#lastScheduled = null;
    this.#scheduleLag = 0;
    this.#offPhase = 0;
    this.#droppedBefore = 0;
  }
  /** The `<div>` this put around the element, so it can be taken away again. */
  #wrapper: HTMLElement | null = null;
  readonly #resizes: ResizeObserver | null;
  #doubleRate: boolean;
  #spatialCheck: boolean;
  #outputSinceReport = 0;
  /** otya GPU pulldown path: enabled by the `film` option (see below). */
  #debug: boolean;
  #film: boolean;
  /** How long a frame lasts in wall time, from what the frames themselves say. */
  #periodMs = 0;
  /** The size of a frame as it is coded, which is what a texture holds. */
  #width = 0;
  #height = 0;
  /** Where the newest frame is. The two before it follow round the ring. */
  #head = HISTORY - 1;
  /** How many of the held frames are consecutive, up to HISTORY. */
  #frames = 0;
  #lastMediaTime = 0;
  /** presentedFrames at the last ingested frame; pairs with #lastMediaTime. */
  #lastPresentedFrames = 0;
  /** A destination frame that arrived before the browser finished seeking. */
  #seekFrameReady = false;
  #running = false;
  /** Cancels work suspended inside a synchronous owner callback. */
  #playbackRevision = 0;
  #enabled = false;
  #destroyed = false;
  #scan: Scan | null = null;
  #videoTimeline: readonly VideoState[] = [];
  #lost = false;
  readonly #onStats: ((stats: DeinterlaceStats) => void) | undefined;
  readonly #onFailure: ((message: string) => void) | undefined;
  readonly #externalHost: ExternalRenderingHost | null;
  #frameSource: TexImageSource;
  readonly #rendering: "auto" | "worker" | "main";
  readonly #workerURL: string | URL | null;
  #worker: Worker | null = null;
  #workerState: "idle" | "starting" | "active" | "main" | "failed";
  #workerRestarted = false;
  #workerGeneration = 0;
  #displayCanvasTransferred = false;
  #workerFrameID = 0;
  #workerFrameInFlight = false;
  #workerAcceptedFrame = false;
  #pendingWorkerFrame: PendingWorkerFrame | null = null;
  #captureID = 0;
  readonly #captureRequests = new Map<
    number,
    { resolve(image: ImageBitmap): void; reject(error: Error): void }
  >();
  /** Everything the next report is counted from. See DeinterlaceStats. */
  #stats = {
    filtered: 0,
    missed: 0,
    degraded: 0,
    discontinuities: 0,
    resynced: 0,
    late: 0,
    queueResetted: 0,
    matched: 0,
  };
  /** `presentedFrames` of the last frame the callback saw; 0 before any. */
  #lastPresented = 0;
  /** When the last frame the filter took arrived, to see the gaps between. */
  #lastFrameAt = 0;
  #reportedAt = 0;
  #renderFramesSinceReport = 0;
  #renderMsSinceReport = 0;
  #showFramesSinceReport = 0;
  #showMsSinceReport = 0;
  #reportMaxQueuedFields = 0;
  readonly #timerQueryExtension: EXT_disjoint_timer_query_webgl2 | null;
  #freeQueries: WebGLQuery[] = [];
  #timerUsingQueries: { q: WebGLQuery; isField: boolean }[] = [];
  #gpuFrameNanosecondsSinceReport = 0;
  #gpuFrameCountSinceReport = 0;
  #gpuFieldNanosecondsSinceReport = 0;
  #gpuFieldCountSinceReport = 0;
  /** The last phase read back from the GPU, and how many frames ago it was for. */
  #known: Phase = NO_PHASE;
  #knownAge = 0;
  /** The phase of the frame being filtered: #known advanced by #knownAge. */
  #phase: Phase = NO_PHASE;
  #filmLocked = false;
  /** Frames left of the FILM_HOLD_FRAMES window that starts when the cadence is held. */
  #filmHold = 0;
  /** Whether the comb counts were made for the frame being filtered and its neighbours. */
  #measured = false;
  /** Whether the frame being filtered may have its fields matched. See #render. */
  #matching = false;
  /** Whether the last detection read back found each frame to be one instant. */
  #oneInstant = false;
  /** Whether comb counts were also made for the frame after it. */
  #aheadMeasured = false;
  /** Whether the frame behind the newest (the one being filtered) came after a gap in the frames seen. */
  #gapBehind = false;
  /** Whether the previous frame was progressive. */
  #afterProgressive = false;
  #debugRenderState: DebugRenderState | null = null;
  #debugText = "";
  /** Debug only: frames given each phase (0 for none), and repeats dropped. */
  #phaseCounts = [0, 0, 0, 0, 0, 0];
  #filmDropped = 0;
  /**
   * Why requested film reconstruction is currently degraded, or null while
   * healthy. The `film` option stays as the caller set it;
   * only the engine stands down, so this is never a silent option change.
   */
  #filmDegraded: string | null = null;
  /** Last worker-reported filmError, to derive the page-side failure event. */
  #workerFilmError: string | null = null;
  #workerFilmFailure = 0;
  /** Whether pictures come from `decodedVideo`. Set by the first push and kept. */
  #decoded = false;
  /** Pushed pictures not yet taken in, in timestamp order. */
  #pending: DecodedPicture[] = [];
  /** Whether finish() was called since the last reset. */
  #finished = false;
  readonly #clock = new MediaClock();
  /** Built when the first decoded picture arrives. */
  #converter: PictureConverter | null = null;
  /** The decoded picture in each history slot; the newest is at #head. */
  readonly #held: HeldPicture[] = Array.from({ length: HISTORY }, () => ({
    timestamp: 0,
    duration: 0,
    interlaced: true,
    topFieldFirst: true,
    repeatFirstField: false,
  }));
  /** Whether a decoded picture has been taken in since the last reset. */
  #taken = false;
  /** Whether the newest picture is still to be filtered against its successor. */
  #awaiting = false;
  /** Whether it has been filtered against itself meanwhile, its successor being late. */
  #awaitingFlushed = false;
  /** Filtered decoded outputs waiting for their media time, in time order. */
  readonly #decodedQueue: DecodedOutput[] = [];
  /** The decoded output on the canvas. */
  #shownOutput: DecodedOutput | null = null;
  /**
   * The first outputs of the last two pictures shown, whose slots are kept:
   * a pause can land in the picture before the one the canvas has gone on to.
   */
  #shownStart: DecodedOutput | null = null;
  #previousStart: DecodedOutput | null = null;
  /** The media time of the output on the canvas; nothing older goes up after it. */
  #shownTime = Number.NEGATIVE_INFINITY;
  /** Outputs the last refresh advanced by. Near a refresh boundary the next refresh does the same. */
  #advanced = 1;
  /** Field order of the decoded picture being filtered. */
  #fieldOrder = true;
  /** The size the decoded pictures are shown at. */
  #displayWidth = 0;
  #displayHeight = 0;
  /** The element's own inline aspect ratio, from before decoded pictures gave it theirs. */
  #elementAspectRatio: string | null = null;
  /** Whether the element answers for the decoded pictures; see `#standInForElement`. */
  #elementStandsIn = false;
  /** Decoded pictures pushed since the counts were last reset. */
  #picturesPushed = 0;
  /** Pictures a Worker renderer dropped unshown, as of its last report. */
  #workerPictureDrops = 0;
  /**
   * Buffers transferred to the Worker and not yet back, by the id they went
   * with. A Worker that goes away takes them with it, and what is handed
   * back for them then is the detached original.
   */
  readonly #sentPictures = new Map<number, ArrayBuffer>();
  #pictureID = 0;
  constructor(video: HTMLVideoElement, options?: DeinterlacerOptions);
  /** @internal Used only to construct the rendering engine inside a Worker. */
  constructor(
    video: HTMLVideoElement,
    options: DeinterlacerOptions,
    externalHost: ExternalRenderingHost,
  );
  constructor(
    video: HTMLVideoElement,
    options: DeinterlacerOptions = {},
    externalHost: ExternalRenderingHost | null = null,
  ) {
    super();
    this.#video = video;
    this.#doubleRate = options.doubleRate ?? false;
    this.#spatialCheck = options.spatialCheck ?? true;
    this.#debug = options.debug ?? false;
    this.#film = options.film ?? false;
    this.#onStats = options.onStats;
    this.#onFailure = options.onFailure;
    this.#externalHost = externalHost;
    this.#rendering = externalHost ? "main" : (options.rendering ?? "main");
    this.#workerURL = options.workerUrl ?? bundledWorkerURL;
    this.#workerState = this.#rendering === "main" ? "main" : "idle";
    this.#displayCanvas = externalHost
      ? (externalHost.canvas as unknown as HTMLCanvasElement)
      : document.createElement("canvas");
    this.#renderCanvas =
      externalHost?.canvas ??
      (this.#rendering === "main"
        ? this.#displayCanvas
        : document.createElement("canvas"));
    this.#frameSource = video;
    // Where it goes is worked out in #layout; the element underneath keeps
    // every click, since all this does is cover it.
    if (!externalHost)
      this.#displayCanvas.style.cssText =
        "position:absolute;pointer-events:none;visibility:hidden";
    const gl = this.#renderCanvas.getContext("webgl2", {
      // Keep the underlying video in Chromium's compositor to receive frame notifications at the source rate.
      alpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      preserveDrawingBuffer: false,
      powerPreference: "high-performance",
    });
    if (!(gl instanceof WebGL2RenderingContext))
      throw new Error("this browser has no WebGL2");
    this.#gl = gl;
    if (this.#film) {
      this.#requireFloatBuffers();
      this.#detector = new FilmDetector(gl);
    }
    this.#program = createProgram(gl, YADIF_FRAGMENT_SHADER);
    const program = this.#program;
    this.#location = Object.fromEntries(
      Object.entries(YADIF_UNIFORMS).map(([key, name]) => [
        key,
        gl.getUniformLocation(program, name),
      ]),
    ) as Record<keyof typeof YADIF_UNIFORMS, WebGLUniformLocation | null>;
    this.#blit = createProgram(gl, BLIT_FRAGMENT_SHADER);
    this.#blitField = gl.getUniformLocation(this.#blit, "uField");
    this.#blitFlip = gl.getUniformLocation(this.#blit, "uFlip");
    this.#timerQueryExtension = gl.getExtension(
      "EXT_disjoint_timer_query_webgl2",
    );
    this.#renderCanvas.addEventListener(
      "webglcontextlost",
      this.#onContextLost,
    );
    // The canvas is placed in pixels rather than in percentages, because where
    // the picture sits inside the element is arithmetic the browser does not
    // hand out. Anything that moves the element has to move it too.
    this.#resizes = externalHost
      ? null
      : new ResizeObserver(() => this.#layout());
    // PiP reports becoming hidden before the DOM moves back, and a move at
    // the same size produces no resize. Observe adoption directly so pending
    // requests follow the canvas even after the old window stops serving them.
    this.#ownerChanges = externalHost
      ? null
      : new MutationObserver(() => {
          if (this.#displayCanvas.ownerDocument !== this.#ownerDocument)
            this.#layout();
        });
    this.decodedVideo = {
      push: (picture) => this.#pushPicture(picture),
      reset: () => this.#resetPictures(),
      finish: () => {
        this.#finished = true;
        this.#worker?.postMessage({
          type: "pictures",
          action: "finish",
        } satisfies WorkerCommand);
      },
      onrelease: null,
    };
    // The watch shares this GL context, so it works only while pictures are
    // drawn here. A Worker renderer is sent frames, not textures.
    this.#pictures = externalHost ? null : new PictureWatch(gl, video);
    this.#videoFrames = new VideoFrames(video, () =>
      this.#workerState === "main" ? this.#pictures : null,
    );
    // A frame the filter has not seen the neighbours of is not worth holding:
    // whatever is next will have been somewhere else entirely.
    video.addEventListener("emptied", this.#onEmptied);
    // The picture changed shape without the element's box changing, which a
    // ResizeObserver has nothing to say about.
    video.addEventListener("resize", this.#onResize);
    // Nothing more is coming, so the frame being held back has to go out now
    // or the last thing a viewer sees is the one before it.
    video.addEventListener("pause", this.#onFlush);
    video.addEventListener("ended", this.#onFlush);
    video.addEventListener("seeking", this.#onSeeking);
    video.addEventListener("seeked", this.#onFlush);
    video.addEventListener("ratechange", this.#onFlush);
    video.addEventListener("waiting", this.#onWaiting);
  }

  /**
   * Whether the canvas, rather than the element, is what shows the picture.
   * A page uses this to decide which of the two to capture or transform.
   * Filtering an element's own picture that is the same as filtering it at
   * all, since a progressive source is left to the element. Decoded pictures
   * are on the canvas filtered or not, because the element has none.
   */
  get running(): boolean {
    if (this.#decoded) return this.#running;
    return this.#running && (this.#scan?.interlaced ?? true);
  }

  /** The HTML canvas currently placed over the media element. */
  get canvas(): HTMLCanvasElement {
    return this.#displayCanvas;
  }

  /** Field order for the current scan state, defaulting to top-field-first. */
  get #topFieldFirst(): boolean {
    if (this.#decoded) return this.#fieldOrder;
    return this.#scan?.topFieldFirst !== false;
  }

  /** The same public filter options for either rendering target. */
  #workerRenderingOptions(): WorkerRenderingOptions {
    return {
      doubleRate: this.#doubleRate,
      spatialCheck: this.#spatialCheck,
      film: this.#film,
      debug: this.#debug,
    };
  }

  /** Whether the caller wants filtering, independently of the current source. */
  get enabled(): boolean {
    return this.#enabled;
  }

  set enabled(enabled: boolean) {
    this.#enabled = enabled;
    this.#apply();
    this.#worker?.postMessage({
      type: "enabled",
      enabled,
    } satisfies WorkerCommand);
  }

  /** Update whether the source needs filtering and which field comes first. */
  set scan(scan: Scan | null) {
    // Decoded pictures carry their own field order.
    if (this.#decoded) return;
    const interlacingChanged = this.#scan?.interlaced !== scan?.interlaced;
    const changed =
      interlacingChanged || this.#scan?.topFieldFirst !== scan?.topFieldFirst;
    this.#scan = scan;
    if (changed && (!this.#recoverFilm() || this.#scan !== scan)) return;
    this.#worker?.postMessage({ type: "scan", scan } satisfies WorkerCommand);
    if (changed) {
      // A standalone caller may update scan metadata without a timeline entry.
      // Do not let history or queued fields measured under the old parity cross
      // the new source state.
      this.#frames = 0;
      this.#dropQueue();
      this.#resetFieldMetrics();
      // Progressive video carries no cadence measurement, so schedule fields
      // only after measuring the first complete interlaced interval
      if (interlacingChanged) this.#periodMs = 0;
      this.#presentedPicture = null;
      this.#setVisible(false);
    }
    this.#apply();
    if (changed) {
      if (
        (scan?.interlaced ?? true) &&
        (this.#externalHost || this.#workerState === "main")
      )
        this.#startLoop();
      else this.#stopLoop();
    }
  }

  get scan(): Scan | null {
    if (this.#decoded) return this.#shownOutput?.scan ?? null;
    return this.#scan;
  }

  set videoTimeline(timeline: readonly VideoState[]) {
    this.#videoTimeline = timeline;
    this.#worker?.postMessage({
      type: "timeline",
      videoTimeline: timeline,
    } satisfies WorkerCommand);
    if (timeline.length === 0) this.#scan = null;
    this.#apply();
  }

  get videoTimeline(): readonly VideoState[] {
    return this.#videoTimeline;
  }

  /**
   * What to put on the screen for fullscreen: the `<div>` holding both the
   * element and the canvas once there is one, and the element itself before
   * that. Fullscreening the element alone would leave the canvas behind in
   * the page, and with it the only deinterlaced picture there is.
   */
  get container(): HTMLElement {
    return this.#wrapper ?? this.#video;
  }

  /** Whether a picture goes up for every field rather than every frame. */
  get doubleRate(): boolean {
    return this.#doubleRate;
  }

  set doubleRate(doubleRate: boolean) {
    if (doubleRate === this.#doubleRate) return;
    this.#doubleRate = doubleRate;
    this.#postWorkerSettings();
    // Decoded outputs carry their own times, so those queued still stand.
    if (this.#decoded) return;
    // A rate change gives every queued field a different presentation cadence,
    // so the next decoded frame starts a new schedule on the current timeline.
    this.#dropQueue();
    this.#applyScheduling();
  }

  get spatialCheck(): boolean {
    return this.#spatialCheck;
  }

  set spatialCheck(spatialCheck: boolean) {
    if (spatialCheck === this.#spatialCheck) return;
    this.#spatialCheck = spatialCheck;
    this.#postWorkerSettings();
  }

  get film(): boolean {
    return this.#film;
  }

  set film(film: boolean) {
    // A degraded engine re-arms on an explicit `film = true`: the identity
    // guard below would otherwise make the documented manual retry a no-op
    // precisely when it is needed (degrade keeps the option on).
    const filmError = this.#worker ? this.#workerFilmError : this.#filmDegraded;
    if (film === this.#film && (film === false || filmError === null)) return;
    if (this.#worker) {
      this.#film = film;
      this.#postWorkerSettings(film ? "film" : undefined);
      return;
    }
    if (film) {
      if (!this.#recoverFilm()) return;
      try {
        this.#ensureDetector();
      } catch (error) {
        // A runtime toggle that cannot build the detector degrades with
        // notice instead of throwing: only construction probes capability
        // with an exception, so the worker's applySettings path and page
        // toggles cannot take the whole deinterlacer down (F5). The option
        // stays on as intent; the engine stands down until a retry point.
        this.#film = true;
        this.#postWorkerSettings();
        this.#degradeFilm(
          `film detector unavailable: ${error instanceof Error ? error.message : String(error)}`,
        );
        return;
      }
    }
    this.#film = film;
    this.#postWorkerSettings();
    if (!film) {
      // Withdrawing the intent clears the error with it: nothing is
      // requested, so nothing is degraded.
      if (!this.#recoverFilm()) return;
      this.#filmLocked = false;
      this.#filmHold = 0;
      this.#matching = false;
      this.#phase = NO_PHASE;
      this.#resetFieldMetrics();
      this.#detector?.destroy();
      this.#detector = null;
    }
    this.#applyScheduling();
  }

  get debug(): boolean {
    return this.#debug;
  }

  set debug(debug: boolean) {
    if (debug === this.#debug) return;
    this.#debug = debug;
    this.#postWorkerSettings();
  }

  /** Whether pictures are queued for presentation by the frame loop. */
  get #scheduled(): boolean {
    return this.#doubleRate || this.#film;
  }

  #applyScheduling(): void {
    if (this.#destroyed || this.#decoded) return;
    if (this.#scheduled) {
      if (this.#width > 0) this.#allocateOutputs();
      if (
        (this.#scan?.interlaced ?? true) &&
        (this.#externalHost || this.#workerState === "main")
      )
        this.#startLoop();
    } else if (!this.#film) {
      // Turning it off leaves fields on their way to a canvas that is about to
      // stop expecting them, and a frame's worth of texture each behind them.
      this.#presentedPicture = null;
      this.#setVisible(false);
      this.#freeOutputs();
    }
  }

  /** Apply mutable filter settings to the existing Worker and canvas. */
  #postWorkerSettings(retryFilm?: "film"): void {
    this.#worker?.postMessage({
      type: "settings",
      options: this.#workerRenderingOptions(),
      retryFilm,
    } satisfies WorkerCommand);
  }

  #requireFloatBuffers(): void {
    if (this.#gl.getExtension("EXT_color_buffer_float") === null)
      throw new Error("film needs EXT_color_buffer_float");
  }

  /** Build the GPU pulldown detector the `film` option needs, or throw. */
  #ensureDetector(): void {
    this.#requireFloatBuffers();
    this.#detector ??= new FilmDetector(this.#gl);
    // A detector built outside #resize has no dimensions; size it now so
    // a runtime toggle engages instead of idling on zero-size targets.
    if (this.#width > 0) this.#detector.resize(this.#width, this.#height);
  }

  #apply(): void {
    // Decoded pictures have nowhere else to go, so they are shown, filtered
    // or not, whatever `enabled` and the timeline say.
    if (
      this.#decoded ||
      (this.#enabled &&
        (this.#videoTimeline.length > 0 || (this.#scan?.interlaced ?? true)))
    )
      this.start();
    else this.stop();
  }

  /** Start the bundled Worker when the required transfer APIs are available. */
  #ensureWorker(): boolean {
    if (this.#externalHost || this.#rendering === "main") return false;
    if (this.#workerState === "starting" || this.#workerState === "active")
      return true;
    const canTransfer =
      typeof Worker !== "undefined" &&
      typeof VideoFrame !== "undefined" &&
      typeof OffscreenCanvas !== "undefined" &&
      this.#workerURL !== null &&
      "transferControlToOffscreen" in HTMLCanvasElement.prototype;
    if (!canTransfer) {
      if (this.#rendering === "auto") {
        this.#fallBackToMain();
        return false;
      }
      this.#workerState = "failed";
      this.#running = false;
      return true;
    }
    this.#startWorker();
    return true;
  }

  /** Transfer the display canvas to a new Worker, replacing it if already transferred. */
  #startWorker(): void {
    this.#closePendingWorkerFrame();
    this.#worker?.terminate();
    this.#worker = null;
    this.#releaseSentPictures();
    this.#workerFrameInFlight = false;
    this.#workerAcceptedFrame = false;
    this.#workerFilmError = null;
    this.#workerFilmFailure = 0;
    let canvas = this.#displayCanvas;
    // Use the published element on the first start. A transferred canvas
    // cannot be transferred again, so recovery needs a fresh element.
    if (this.#displayCanvasTransferred) {
      canvas = document.createElement("canvas");
      canvas.className = this.#displayCanvas.className;
      const style = this.#displayCanvas.getAttribute("style");
      if (style === null) canvas.removeAttribute("style");
      else canvas.setAttribute("style", style);
      canvas.style.visibility = "hidden";
      if (this.#displayCanvas.parentElement)
        this.#displayCanvas.replaceWith(canvas);
      this.#displayCanvas = canvas;
    }

    const generation = ++this.#workerGeneration;
    this.#workerState = "starting";
    let worker: Worker;
    let offscreen: OffscreenCanvas;
    try {
      // Transfer is one-way. Falling back after this point uses the separate
      // rendering canvas whose control still belongs to the main thread.
      offscreen = canvas.transferControlToOffscreen();
      this.#displayCanvasTransferred = true;
      worker = new Worker(this.#workerURL!, { type: "module" });
    } catch (error) {
      this.#workerFailed(
        error instanceof Error ? error.message : String(error),
      );
      return;
    }
    this.#worker = worker;
    worker.onmessage = (event: MessageEvent<WorkerNotification>) => {
      if (generation === this.#workerGeneration)
        this.#onWorkerMessage(event.data);
    };
    worker.onerror = (event) => {
      if (generation !== this.#workerGeneration) return;
      event.preventDefault();
      this.#workerFailed(event.message || "the deinterlacer worker failed");
    };
    worker.postMessage(
      {
        type: "initialize",
        canvas: offscreen,
        options: this.#workerRenderingOptions(),
        scan: this.#scan,
        videoTimeline: this.#videoTimeline,
        enabled: this.#running,
        video: this.#workerVideoState(),
      } satisfies WorkerCommand,
      [offscreen],
    );
  }

  /** Apply Worker notifications and release the wait for the next input frame. */
  #onWorkerMessage(notification: WorkerNotification): void {
    switch (notification.type) {
      case "ready":
        this.#workerState = "active";
        if (this.#running) {
          this.#request();
          this.#startCaptureLoop();
        }
        break;
      case "failed":
        this.#workerFailed(notification.message);
        break;
      case "consumed": {
        this.#workerFrameInFlight = false;
        this.#workerAcceptedFrame = true;
        const pending = this.#pendingWorkerFrame;
        this.#pendingWorkerFrame = null;
        if (pending) this.#sendWorkerFrame(pending);
        break;
      }
      case "visibility":
        this.#displayCanvas.style.visibility = notification.visible
          ? "visible"
          : "hidden";
        break;
      case "stats": {
        if (this.#decoded)
          this.#workerPictureDrops =
            notification.stats.missed + notification.stats.queueResetted;
        const stats: DeinterlaceStats = {
          ...notification.stats,
          dropped:
            this.#video.getVideoPlaybackQuality?.().droppedVideoFrames ?? 0,
        };
        // A retry and an identical failure can both occur between reports.
        // The Worker counts episodes so that this is still a new failure.
        const workerFilmError = stats.filmError ?? null;
        const previousFailure = this.#workerFilmFailure;
        // A failure listener may synchronously request another attempt.
        this.#workerFilmError = workerFilmError;
        this.#workerFilmFailure = notification.filmFailure;
        if (
          workerFilmError !== null &&
          notification.filmFailure !== previousFailure
        ) {
          this.dispatchEvent(
            new CustomEvent("failure", { detail: workerFilmError }),
          );
          try {
            this.#onFailure?.(workerFilmError);
          } catch {
            // A failing failure-listener must not break the frame loop.
          }
        }
        this.dispatchEvent(new CustomEvent("stats", { detail: stats }));
        this.#onStats?.(stats);
        break;
      }
      case "capture": {
        const request = this.#captureRequests.get(notification.id);
        this.#captureRequests.delete(notification.id);
        if (!request) {
          notification.image?.close();
          break;
        }
        if (notification.image) request.resolve(notification.image);
        else if (this.#decoded)
          request.reject(new Error("no rendered picture is available"));
        else
          void createImageBitmap(this.#video).then(
            request.resolve,
            request.reject,
          );
        break;
      }
      case "release":
        if (this.#sentPictures.delete(notification.id))
          this.#release(notification.data);
        break;
    }
  }

  /**
   * Tell the owner that a rendering resource failed after construction.
   * In the worker domain the boundary counts episodes: the reason travels in
   * `stats.filmError` and the page derives the event from the episode count,
   * so a film degradation is never mistaken for worker death.
   */
  #notifyFailure(message: string): void {
    this.dispatchEvent(new CustomEvent("failure", { detail: message }));
    if (this.#externalHost) return;
    try {
      this.#onFailure?.(message);
    } catch {
      // A failing failure-listener must not break the frame loop.
    }
  }

  /**
   * Stand down film reconstruction without touching the caller's options.
   * Pictures keep flowing through plain YADIF; the reason is reported once
   * per episode through the failure event/option and `stats.filmError`.
   * Silently turning the `film` option off is not a fallback -- it would
   * rewrite the caller's 24fps intent -- so the option stays on and only
   * the engine stands down.
   */
  #degradeFilm(reason: string): void {
    // A repeated identical reason stays one episode; a different reason is
    // new information and notifies again (F11).
    if (this.#filmDegraded === reason) return;
    this.#filmDegraded = reason;
    this.#filmLocked = false;
    this.#filmHold = 0;
    this.#matching = false;
    this.#phase = NO_PHASE;
    this.#resetFieldMetrics();
    // A detector that threw once would throw every frame; drop it so the
    // loop does useful work until a retry point rebuilds it.
    this.#detector?.destroy();
    this.#detector = null;
    this.#notifyFailure(reason);
  }

  /**
   * Re-arm film reconstruction at a resource-reallocation point (start, scan
   * change, resize, or re-setting the option). The next frame retries; a
   * repeated failure degrades again and notifies as a new episode.
   */
  #recoverFilm(): boolean {
    if (this.#destroyed) return false;
    if (this.#worker) return true;
    this.#filmDegraded = null;
    return true;
  }

  /** Retry a transient Worker failure once, then show the media element if it fails again. */
  #workerFailed(message: string): void {
    if (
      this.#workerState === "starting" &&
      this.#rendering === "auto" &&
      !this.#workerRestarted
    ) {
      this.#fallBackToMain();
      return;
    }
    this.#rejectCaptureRequests(message);
    if (!this.#workerRestarted) {
      this.#workerRestarted = true;
      this.#startWorker();
      return;
    }
    console.error(`Deinterlacer Worker stopped: ${message}`);
    this.#workerState = "failed";
    this.#worker?.terminate();
    this.#worker = null;
    this.#closePendingWorkerFrame();
    this.#releaseSentPictures();
    this.#notifyFailure(`deinterlacer worker stopped: ${message}`);
    this.stop();
  }

  /** Restore the main-thread canvas when automatic Worker selection fails. */
  #fallBackToMain(): void {
    const mainCanvas = this.#renderCanvas as HTMLCanvasElement;
    mainCanvas.className = this.#displayCanvas.className;
    const style = this.#displayCanvas.getAttribute("style");
    if (style === null) mainCanvas.removeAttribute("style");
    else mainCanvas.setAttribute("style", style);
    mainCanvas.style.visibility = "hidden";
    if (this.#displayCanvas.parentElement)
      this.#displayCanvas.replaceWith(mainCanvas);
    this.#displayCanvas = mainCanvas;
    this.#displayCanvasTransferred = false;
    this.#worker?.terminate();
    this.#worker = null;
    this.#workerState = "main";
    this.#closePendingWorkerFrame();
    this.#releaseSentPictures();
    if (this.#running) {
      this.#request();
      this.#startCaptureLoop();
      if (this.#scan?.interlaced ?? true) this.#startLoop();
    }
  }

  /** Close the queued frame still owned by the page when switching renderers. */
  #closePendingWorkerFrame(): void {
    this.#pendingWorkerFrame?.frame.close();
    this.#pendingWorkerFrame = null;
  }

  /** Reject captures whose replies would be lost when the Worker is rebuilt. */
  #rejectCaptureRequests(message: string): void {
    for (const request of this.#captureRequests.values())
      request.reject(new Error(message));
    this.#captureRequests.clear();
  }

  start(): void {
    if (this.#running || this.#destroyed || this.#lost) return;
    this.#playbackRevision++;
    this.#running = true;
    this.#resetStats();
    // A new playback retries film detection if it was requested.
    if (!this.#recoverFilm()) return;
    this.#mount();
    this.#startCaptureLoop();
    if (this.#ensureWorker()) {
      if (this.#decoded) {
        // The page reads the clock for the Worker on its own refreshes.
        this.#worker?.postMessage({
          type: "running",
          running: true,
        } satisfies WorkerCommand);
        this.#startLoop();
        return;
      }
      // `start()` can be called without going through the `enabled` setter,
      // so an existing Worker needs the enabled state explicitly.
      this.#worker?.postMessage({
        type: "enabled",
        enabled: true,
      } satisfies WorkerCommand);
      // An active Worker will not send `ready` again. Re-arm the frame
      // callback that `stop()` cancelled.
      if (this.#workerState === "active") this.#request();
      return;
    }
    this.#request();
    if (this.#decoded || (this.#scan?.interlaced ?? true)) this.#startLoop();
  }

  /**
   * Take the deinterlaced picture away, leaving the element's own showing.
   * Decoded pictures held are released, and those pushed until the next
   * start() are released at once.
   */
  stop(): void {
    this.#playbackRevision++;
    if (!this.#running) return;
    this.#running = false;
    if (this.#decoded) this.#resetPictures();
    this.#videoFrames.cancel();
    this.#stopCaptureLoop();
    this.#stopLoop();
    this.#frames = 0;
    this.#presentedPicture = null;
    this.#setVisible(false);
    this.#closePendingWorkerFrame();
    // A Worker showing decoded pictures keeps showing them whatever
    // `enabled` says, so it is stopped as such.
    this.#worker?.postMessage(
      this.#decoded
        ? ({ type: "running", running: false } satisfies WorkerCommand)
        : ({ type: "enabled", enabled: false } satisfies WorkerCommand),
    );
  }

  destroy(): void {
    if (this.#destroyed) return;
    this.#destroyed = true;
    this.#enabled = false;
    this.stop();
    this.#worker?.postMessage({ type: "destroy" } satisfies WorkerCommand);
    this.#worker?.terminate();
    this.#worker = null;
    this.#closePendingWorkerFrame();
    this.#releaseSentPictures();
    this.#rejectCaptureRequests("the deinterlacer was destroyed");
    // `stop()` cancelled both requests on whichever window held them; the
    // listener that would have re-armed them goes with the same move.
    this.#ownerDocument?.removeEventListener(
      "visibilitychange",
      this.#onOwnerVisibility,
    );
    this.#ownerDocument = null;
    this.#ownerChanges?.disconnect();
    this.#renderCanvas.removeEventListener(
      "webglcontextlost",
      this.#onContextLost,
    );
    this.#videoFrames.destroy();
    this.#pictures?.destroy();
    this.#video.removeEventListener("emptied", this.#onEmptied);
    this.#video.removeEventListener("resize", this.#onResize);
    this.#video.removeEventListener("pause", this.#onFlush);
    this.#video.removeEventListener("ended", this.#onFlush);
    this.#video.removeEventListener("seeking", this.#onSeeking);
    this.#video.removeEventListener("seeked", this.#onFlush);
    this.#video.removeEventListener("ratechange", this.#onFlush);
    this.#video.removeEventListener("waiting", this.#onWaiting);
    if (this.#elementAspectRatio !== null)
      this.#video.style.aspectRatio = this.#elementAspectRatio;
    this.#stopStandingIn();
    this.#unmount();
    for (const texture of this.#textures) this.#gl.deleteTexture(texture);
    this.#textures = [];
    this.#freeOutputs();
    for (const q of [
      ...this.#freeQueries,
      ...this.#timerUsingQueries.map(({ q }) => q),
    ]) {
      this.#gl.deleteQuery(q);
    }
    this.#freeQueries.length = 0;
    this.#timerUsingQueries.length = 0;
    this.#detector?.destroy();
    this.#detector = null;
    this.#converter?.destroy();
    this.#converter = null;
    if (this.#debugRenderState !== null) {
      destroyDebugRenderState(this.#debugRenderState);
      this.#debugRenderState = null;
    }
    this.#gl.deleteProgram(this.#program);
    this.#gl.deleteProgram(this.#blit);
    this.#gl.getExtension("WEBGL_lose_context")?.loseContext();
  }

  /**
   * Copy the picture currently represented by the deinterlacer.
   *
   * The WebGL drawing buffer is deliberately not preserved between browser
   * composites. Repeating the exact draw path of the presented picture before
   * `createImageBitmap` makes a snapshot reliable without imposing the
   * permanent cost of `preserveDrawingBuffer` on ordinary playback.
   */
  capture(): Promise<ImageBitmap> {
    if (
      this.#workerState === "active" &&
      this.#displayCanvas.style.visibility === "visible" &&
      this.#worker
    ) {
      const id = ++this.#captureID;
      const image = new Promise<ImageBitmap>((resolve, reject) => {
        this.#captureRequests.set(id, { resolve, reject });
      });
      this.#worker.postMessage({
        type: "capture",
        id,
        width: this.#video.videoWidth,
        height: this.#video.videoHeight,
      } satisfies WorkerCommand);
      return image;
    }
    if (
      !this.#decoded &&
      (this.#workerState === "starting" || this.#workerState === "failed")
    )
      return createImageBitmap(this.#video);
    const picture = this.#presentedPicture;
    // Without a video track the element has no picture to fall back on.
    if (
      (this.#externalHost || this.#decoded) &&
      (!this.#running || this.#lost || !picture)
    )
      return Promise.reject(new Error("no rendered picture is available"));
    if (!this.#running || this.#lost || !picture)
      return createImageBitmap(this.#video);
    if (picture.kind === "texture")
      this.#showTexture(picture.texture, picture.flip, false);
    else this.#render(picture.flush, picture.second, null, false);
    const width = this.#decoded ? this.#displayWidth : this.#video.videoWidth;
    const height = this.#decoded
      ? this.#displayHeight
      : this.#video.videoHeight;
    if (
      width > 0 &&
      height > 0 &&
      (width !== this.#renderCanvas.width ||
        height !== this.#renderCanvas.height)
    )
      return createImageBitmap(this.#renderCanvas, {
        resizeWidth: width,
        resizeHeight: height,
        resizeQuality: "high",
      });
    return createImageBitmap(this.#renderCanvas);
  }

  override addEventListener<K extends keyof DeinterlacerEventMap>(
    type: K,
    listener: (event: DeinterlacerEventMap[K]) => void,
    options?: boolean | AddEventListenerOptions,
  ): void;
  override addEventListener(
    type: string,
    listener: EventListenerOrEventListenerObject | null,
    options?: boolean | AddEventListenerOptions,
  ): void;
  override addEventListener(
    type: string,
    listener: EventListenerOrEventListenerObject | null,
    options?: boolean | AddEventListenerOptions,
  ): void {
    super.addEventListener(type, listener, options);
  }

  override removeEventListener<K extends keyof DeinterlacerEventMap>(
    type: K,
    listener: (event: DeinterlacerEventMap[K]) => void,
    options?: boolean | EventListenerOptions,
  ): void;
  override removeEventListener(
    type: string,
    listener: EventListenerOrEventListenerObject | null,
    options?: boolean | EventListenerOptions,
  ): void;
  override removeEventListener(
    type: string,
    listener: EventListenerOrEventListenerObject | null,
    options?: boolean | EventListenerOptions,
  ): void {
    super.removeEventListener(type, listener, options);
  }

  #request(): void {
    if (this.#externalHost || !this.#running || this.#decoded) return;
    this.#videoFrames.request(this.#onFrame);
  }

  /** Copy the element's playback state for seek and presentation timing decisions. */
  #workerVideoState(): WorkerVideoState {
    const buffered: Array<{ start: number; end: number }> = [];
    for (let index = 0; index < this.#video.buffered.length; index++)
      buffered.push({
        start: this.#video.buffered.start(index),
        end: this.#video.buffered.end(index),
      });
    return {
      currentTime: this.#video.currentTime,
      playbackRate: this.#video.playbackRate,
      seeking: this.#video.seeking,
      paused: this.#video.paused,
      ended: this.#video.ended,
      readyState: this.#video.readyState,
      videoWidth: this.#video.videoWidth,
      videoHeight: this.#video.videoHeight,
      buffered,
    };
  }

  /** Keep one frame in flight and the newest one waiting, staying close to the audio clock. */
  #queueWorkerFrame(
    now: DOMHighResTimeStamp,
    metadata: FrameObservation,
    captured?: VideoFrame,
  ): void {
    let frame: VideoFrame;
    try {
      frame =
        captured?.clone() ??
        new VideoFrame(this.#video, {
          timestamp: Math.max(0, Math.round(metadata.mediaTime * 1_000_000)),
        });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      // Failure to create the first frame means this browser cannot use the
      // Worker path. Automatic selection falls back to main-thread rendering.
      if (
        this.#rendering === "auto" &&
        !this.#workerAcceptedFrame &&
        !this.#workerRestarted
      ) {
        this.#fallBackToMain();
        this.#processFrame(now, metadata);
      } else {
        this.#workerFailed(message);
      }
      return;
    }
    const pending: PendingWorkerFrame = {
      id: ++this.#workerFrameID,
      frame,
      now,
      metadata,
      video: this.#workerVideoState(),
    };
    if (this.#workerFrameInFlight) {
      this.#pendingWorkerFrame?.frame.close();
      this.#pendingWorkerFrame = pending;
      return;
    }
    this.#sendWorkerFrame(pending);
  }

  /** Transfer the selected frame once the Worker has released the previous input. */
  #sendWorkerFrame(pending: PendingWorkerFrame): void {
    const worker = this.#worker;
    if (!worker || this.#workerState !== "active") {
      pending.frame.close();
      return;
    }
    this.#workerFrameInFlight = true;
    // Built out rather than spread: `pending.now` is this realm's ingestion
    // clock and has no meaning on the other side of the boundary, so it stays
    // off the wire. The clock the Worker does need travels in the metadata.
    const command: WorkerCommand = {
      type: "frame",
      id: pending.id,
      frame: pending.frame,
      metadata: pending.metadata,
      video: pending.video,
    };
    try {
      worker.postMessage(command, [pending.frame]);
    } catch (error) {
      this.#workerFrameInFlight = false;
      pending.frame.close();
      const message = error instanceof Error ? error.message : String(error);
      // A first-transfer failure means the path is unsupported. Rebuild only
      // after the Worker has demonstrated that it can consume frames.
      if (
        this.#rendering === "auto" &&
        !this.#workerAcceptedFrame &&
        !this.#workerRestarted
      ) {
        this.#fallBackToMain();
        this.#processFrame(pending.now, pending.metadata);
      } else {
        this.#workerFailed(message);
      }
    }
  }

  #drawText(text: string, x: number, y: number): void {
    if (this.#debugRenderState == null) {
      this.#debugRenderState = initDebugRenderState(this.#gl, "20px monospace");
    }
    drawText(this.#debugRenderState, text, x, y, this.#width, this.#height, 20);
  }

  #beginGpuTimer(isField: boolean): WebGLQuery | undefined {
    if (this.#timerQueryExtension == null) {
      return undefined;
    }
    if (this.#timerUsingQueries.length > 30) {
      return undefined;
    }
    const q = this.#freeQueries.pop() ?? this.#gl.createQuery();
    this.#gl.beginQuery(this.#timerQueryExtension.TIME_ELAPSED_EXT, q);
    this.#timerUsingQueries.push({ q, isField });
    return q;
  }

  #endGpuTimer(q: WebGLQuery | undefined): void {
    if (this.#timerQueryExtension == null) {
      return;
    }
    if (q != null) {
      this.#gl.endQuery(this.#timerQueryExtension.TIME_ELAPSED_EXT);
    }
    this.#timerUsingQueries = this.#timerUsingQueries.filter(
      ({ q, isField }) => {
        if (this.#gl.getQueryParameter(q, this.#gl.QUERY_RESULT_AVAILABLE)) {
          const result = this.#gl.getQueryParameter(q, this.#gl.QUERY_RESULT);
          if (isField) {
            this.#gpuFieldNanosecondsSinceReport += result;
            this.#gpuFieldCountSinceReport++;
          } else {
            this.#gpuFrameNanosecondsSinceReport += result;
            this.#gpuFrameCountSinceReport++;
          }
          this.#freeQueries.push(q);
          return false;
        }
        return true;
      },
    );
  }

  /**
   * Restart the detection. `gap` is for frames that went unseen in a stream
   * that carries on: the cadence must be found again, but the one-instant
   * verdict is kept because it has not changed.
   */
  #resetFieldMetrics(gap = false): void {
    this.#phase = NO_PHASE;
    this.#known = NO_PHASE;
    this.#knownAge = 0;
    if (!gap) this.#oneInstant = false;
    this.#filmLocked = false;
    this.#detector?.reset(gap);
  }

  /** Detect the pulldown phase of the frame being filtered on the GPU. */
  #detect(): void {
    const { prev, cur, next } = this.#neighbours(false);
    const prevTexture = this.#textures[prev];
    const curTexture = this.#textures[cur];
    const nextTexture = this.#textures[next];
    if (!prevTexture || !curTexture || !nextTexture) return;
    const first = this.#topFieldFirst ? 0 : 1;
    // The same two frames the film branch of the filter weaves from. Count
    // first, because detect() scores the frame from these counts.
    this.#detector?.measureComb(prevTexture, curTexture, first);
    this.#detector?.detect(curTexture, nextTexture, first);
  }

  /**
   * Count the combing for the frame after the one being filtered. The count
   * says whether that frame's first field fits between this frame's
   * second-field lines. Returns whether the count was made.
   */
  #measureAhead(): boolean {
    const { cur, next } = this.#neighbours(false);
    const curTexture = this.#textures[cur];
    const nextTexture = this.#textures[next];
    const detector = this.#detector;
    if (!curTexture || !nextTexture || !detector) return false;
    const first = this.#topFieldFirst ? 0 : 1;
    try {
      detector.measureComb(curTexture, nextTexture, first, true);
    } catch (error) {
      this.#degradeFilm(
        `film detection failed: ${error instanceof Error ? error.message : String(error)}`,
      );
      return false;
    }
    return true;
  }

  /**
   * Read back the previous frame's phase if it has arrived, and advance it
   * to the frame being filtered. The run is not advanced: only the GPU
   * counts observed frames.
   */
  #collectPhase(): void {
    const known = this.#detector?.poll() ?? null;
    if (known !== null) {
      this.#known = known;
      this.#knownAge = known.age;
      this.#oneInstant = known.instant;
    }
    this.#knownAge++;
    const { phase, run } = this.#known;
    // Keep the same wall-clock allowance for GPU readback at higher playback rates.
    if (
      phase === 0 ||
      this.#knownAge >
        Math.ceil(PULLDOWN_FRAMES * Math.max(1, this.#video.playbackRate))
    ) {
      this.#phase = NO_PHASE;
    } else {
      this.#phase = {
        phase: ((phase - 1 + this.#knownAge) % PULLDOWN_FRAMES) + 1,
        run,
      };
    }
  }

  #describePhase(frame: number): string {
    const columns: string[] = [];
    // Debug-only path; only reachable with the detector built.
    const metrics = this.#detector?.metrics ?? new Float32Array(0);
    for (let index = 0; index < FIELD_METRICS.phase; index++) {
      const max = metrics[index * 4] ?? 0;
      const differing = metrics[index * 4 + 1] ?? 0;
      const mean = metrics[index * 4 + 2] ?? 0;
      columns.push(
        `${max.toFixed(3)},${differing.toString().padStart(4)},${mean.toFixed(3)}`,
      );
    }
    const counts = this.#phaseCounts
      .map((count, phase) => `${phase === 0 ? "-" : phase}:${count}`)
      .join(" ");
    return (
      `frame=${frame} phase=${this.#phase.phase} run=${this.#phase.run}` +
      ` known=${this.#known.phase}/${this.#known.run} age=${this.#knownAge}` +
      ` ${this.#filmLocked ? "film" : "video"} period=${this.#periodMs.toFixed(3)}\n` +
      `${columns.join(" ")}\n${counts} dropped:${this.#filmDropped}`
    );
  }

  /**
   * A timestamp taken on `origin`'s clock, expressed on this realm's.
   *
   * `performance.timeOrigin` is defined against the same moment in every
   * realm, so the difference between two origins is the whole of the
   * conversion between their clocks (W3C HR-Time 1.2). The origins are
   * subtracted from one another before the timestamp is added: they are the
   * large numbers, their difference is not, and doing it the other way round
   * would spend the precision the schedule is measured in.
   */
  #localTime(timestamp: number, origin: number): number {
    const offset = origin - performance.timeOrigin;
    // Same realm, which is every case but a Worker renderer and a video node
    // a picture-in-picture window has adopted: leave the value untouched. An
    // origin that is not a number leaves it untouched as well rather than
    // turning the timestamp into one -- the callers below still check that
    // what comes back can describe the frame.
    return Number.isFinite(offset) && offset !== 0
      ? timestamp + offset
      : timestamp;
  }

  /**
   * When this frame reaches the screen, on the clock this renderer draws by.
   *
   * requestVideoFrameCallback()'s display time is what holds the schedule on
   * the refresh grid, so it is preferred wherever it is usable -- including
   * across realms, since #localTime converts it exactly. It is not always
   * usable: 0 and NaN have both been reported, an origin may be missing, and
   * a time that cannot belong to this frame is worse than no time at all.
   * Those fall back to the moment the frame was taken in hand, which is this
   * renderer's own clock and always valid.
   */
  #displayTime(metadata: FrameObservation, now: number): number {
    const expected = metadata.expectedDisplayTime;
    if (!Number.isFinite(expected) || expected <= 0) return now;
    // A missing origin cannot be translated, and an untranslated page clock is
    // not this renderer's; the reach below would reject it, but say so here.
    if (!Number.isFinite(metadata.timeOrigin)) return now;
    const at = this.#localTime(expected, metadata.timeOrigin);
    const reach =
      DISPLAY_TIME_REACH * Math.max(this.#refreshMs, this.#periodMs);
    if (at < now - reach || at > now + reach) return now;
    return at;
  }

  #onFrame = (now: DOMHighResTimeStamp, metadata: FrameMetadata): void => {
    if (!this.#running || this.#lost) return;
    // A frame may arrive before the DOM observer runs; move pending drawing
    // requests to the current window here as well.
    this.#followOwner();
    // The acquisition reports on the clock of whichever window owns the video
    // node; the statistics interval and presentation queue use this realm's
    // clock. Convert the timestamp here, and let the display time travel with its own
    // origin so that a Worker renderer can convert it in turn.
    const at = this.#localTime(now, metadata.timeOrigin);
    // Pass frames only to their explicit transfer destination, excluding them from Worker metadata.
    // Likewise, a take is valid only in this context, so it is excluded too.
    const { frame, picture, ...observation } = metadata;
    this.#frameSource = frame ?? this.#video;
    this.#stagedPicture = picture ?? null;
    try {
      this.#ingestFrame(at, observation, frame);
    } finally {
      this.#frameSource = this.#video;
      this.#stagedPicture = null;
    }
    this.#request();
  };

  /**
   * Take a frame from either acquisition path into the selected renderer.
   * `now` is the ingestion time on this realm's clock.
   */
  #ingestFrame(
    now: DOMHighResTimeStamp,
    metadata: FrameObservation,
    frame?: VideoFrame,
  ): void {
    if (this.#workerState === "active") {
      this.#queueWorkerFrame(now, metadata, frame);
      return;
    }
    if (this.#workerState !== "starting") this.#processFrame(now, metadata);
  }

  /**
   * @internal Feed Worker input through the same history and rendering decisions
   * as main-thread input. `now` is the ingestion time on the Worker's clock.
   * The metadata's display time stays on the page's clock and is converted
   * using the accompanying timeOrigin.
   */
  ingestExternalFrame(
    now: DOMHighResTimeStamp,
    metadata: FrameObservation,
    frame: VideoFrame,
  ): void {
    this.#frameSource = frame;
    try {
      this.#processFrame(now, metadata);
    } finally {
      this.#frameSource = this.#video;
    }
  }

  /** Queue a pushed picture in timestamp order. */
  #pushPicture(picture: DecodedPicture): void {
    try {
      checkPicture(picture);
      if (!this.#decoded) this.#useDecoded();
    } catch (error) {
      this.#release(picture.data);
      throw error;
    }
    this.#picturesPushed++;
    this.#setDisplaySize(picture.displayWidth, picture.displayHeight);
    // Stopped, destroyed or without a context: nothing will show it.
    if (!this.#running) {
      this.#release(picture.data);
      return;
    }
    if (this.#workerState === "starting" || this.#workerState === "active") {
      this.#sendPicture(picture);
      return;
    }
    if (
      this.#taken &&
      picture.timestamp <
        this.#held[this.#head]!.timestamp + TIMESTAMP_TOLERANCE
    ) {
      // Older than a picture already taken in, so it cannot join the history.
      this.#countMissed(picture.timestamp + picture.duration);
      this.#release(picture.data);
      return;
    }
    const pending = this.#pending;
    let index = pending.length;
    while (index > 0 && pending[index - 1]!.timestamp > picture.timestamp)
      index--;
    pending.splice(index, 0, picture);
    this.#dropPassed(this.#clock.at(performance.now()));
    const limit = Math.ceil(
      PICTURE_QUEUE * Math.max(1, this.#video.playbackRate),
    );
    while (pending.length > limit) {
      this.#stats.queueResetted++;
      this.#release(pending.pop()!.data);
    }
    this.#reportMaxQueuedFields = Math.max(
      this.#reportMaxQueuedFields,
      pending.length,
    );
  }

  /**
   * Note the size decoded pictures are shown at. An element playing only
   * sound has no proportions of its own, and a page that sizes its player
   * from the element's would lay it out as 2:1, so the element is given the
   * picture's.
   */
  #setDisplaySize(width: number, height: number): void {
    if (width === this.#displayWidth && height === this.#displayHeight) return;
    this.#displayWidth = width;
    this.#displayHeight = height;
    // A Worker's renderer has no element, and one that has been destroyed
    // has given the element back.
    if (this.#externalHost || this.#destroyed) {
      this.#layout();
      return;
    }
    this.#elementAspectRatio ??= this.#video.style.aspectRatio;
    this.#video.style.aspectRatio = `${width} / ${height}`;
    this.#standInForElement();
    // An element says its picture changed size with this event, and what it
    // now reports has. The layout follows from it as from any other.
    this.#video.dispatchEvent(new Event("resize"));
  }

  /**
   * Let the element answer for the pictures it does not carry. A page reads
   * a video's size and frame counts from the element -- to refuse a capture
   * of nothing, to shape a picture-in-picture placeholder, to show them --
   * and an element playing only the sound says 0 by 0 and no frames. So it
   * is given the decoded pictures' answers as properties of its own, which
   * hide the built-in ones until `destroy` takes them away again.
   */
  #standInForElement(): void {
    if (this.#elementStandsIn) return;
    this.#elementStandsIn = true;
    const video = this.#video;
    Object.defineProperty(video, "videoWidth", {
      configurable: true,
      get: () => this.#displayWidth,
    });
    Object.defineProperty(video, "videoHeight", {
      configurable: true,
      get: () => this.#displayHeight,
    });
    Object.defineProperty(video, "getVideoPlaybackQuality", {
      configurable: true,
      value: (): VideoPlaybackQuality => ({
        creationTime: performance.now(),
        totalVideoFrames: this.#picturesPushed,
        // Whole pictures that were never shown: too late to be taken in, or
        // more than are held. A Worker renderer keeps its own count.
        droppedVideoFrames:
          this.#stats.missed +
          this.#stats.queueResetted +
          this.#workerPictureDrops,
        corruptedVideoFrames: 0,
      }),
    });
  }

  /** Give the element's own size and frame counts back. */
  #stopStandingIn(): void {
    if (!this.#elementStandsIn) return;
    this.#elementStandsIn = false;
    const video = this.#video as unknown as Record<string, unknown>;
    delete video.videoWidth;
    delete video.videoHeight;
    delete video.getVideoPlaybackQuality;
  }

  /** Transfer a picture to the Worker, which sends its buffer back when done. */
  #sendPicture(picture: DecodedPicture): void {
    const id = ++this.#pictureID;
    try {
      this.#worker!.postMessage(
        { type: "picture", id, picture } satisfies WorkerCommand,
        [picture.data],
      );
    } catch (error) {
      // Not transferred, so still the producer's to have back.
      this.#release(picture.data);
      throw error;
    }
    this.#sentPictures.set(id, picture.data);
  }

  /** Hand back the buffers a Worker that is going away still holds. */
  #releaseSentPictures(): void {
    const sent = [...this.#sentPictures.values()];
    this.#sentPictures.clear();
    for (const data of sent) this.#release(data);
  }

  /** Make pushed pictures the only pictures shown, from now on. */
  #useDecoded(): void {
    this.#converter = new PictureConverter(this.#gl);
    this.#decoded = true;
    this.#closePendingWorkerFrame();
    this.#videoFrames.cancel();
    this.#stopCaptureLoop();
    this.#frames = 0;
    this.#dropQueue();
    this.#resetFieldMetrics();
    this.#presentedPicture = null;
    // The first picture sizes everything.
    this.#width = 0;
    this.#height = 0;
    this.#clock.hold();
    this.#apply();
    this.#startLoop();
  }

  /** Hand a picture's buffer back to the producer. */
  #release(data: ArrayBuffer): void {
    const release = this.decodedVideo.onrelease;
    if (release === null) return;
    try {
      release(data);
    } catch (error) {
      // The producer's failure is its own and must not stop the pictures.
      queueMicrotask(() => {
        throw error;
      });
    }
  }

  /** Release everything pushed and forget the history, keeping the canvas as it is. */
  #resetPictures(): void {
    if (!this.#decoded) return;
    this.#worker?.postMessage({
      type: "pictures",
      action: "reset",
    } satisfies WorkerCommand);
    const pending = this.#pending;
    this.#pending = [];
    this.#finished = false;
    this.#taken = false;
    this.#awaiting = false;
    this.#awaitingFlushed = false;
    this.#frames = 0;
    this.#dropQueue();
    this.#shownStart = null;
    this.#previousStart = null;
    this.#shownTime = Number.NEGATIVE_INFINITY;
    this.#advanced = 1;
    this.#resetFieldMetrics();
    this.#filmHold = 0;
    this.#clock.hold();
    for (const picture of pending) this.#release(picture.data);
  }

  /** Release pictures that will neither be shown nor be the neighbour of one that is. */
  #dropPassed(time: number): void {
    const pending = this.#pending;
    while (pending.length > 2 && pending[2]!.timestamp <= time) {
      const passed = pending.shift()!;
      this.#countMissed(passed.timestamp + passed.duration);
      this.#release(passed.data);
    }
  }

  /**
   * Whether something that ended at `end` was there to be shown. What ended
   * at or before the place playback last started from was not: the pictures
   * a seek's target is given as the filter's neighbours, and whatever was
   * still queued when the position jumped past it. Before the first reading
   * of the clock nothing is known to have been skipped.
   */
  #wasDue(end: number): boolean {
    return !(end <= this.#clock.origin + TIMESTAMP_TOLERANCE);
  }

  /** Count a decoded picture ending at `end` that was dropped unshown. */
  #countMissed(end: number): void {
    if (this.#wasDue(end)) this.#stats.missed++;
  }

  /** Read the element's clock, as it was at `wall` on this realm's clock. */
  #observeClock(wall: number): void {
    const video = this.#video;
    if (
      this.#clock.observe(
        wall,
        video.currentTime,
        video.playbackRate,
        !video.paused && !video.seeking && !video.ended,
      )
    ) {
      this.#stats.resynced++;
      this.#advanced = 1;
    }
  }

  /**
   * @internal Give a Worker renderer a reading of the element's clock, taken
   * at `at` on the clock whose origin is `timeOrigin`. The element state it
   * belongs to has been applied to the Worker's video.
   */
  observeMediaClock(at: number, timeOrigin: number): void {
    this.#observeClock(this.#localTime(at, timeOrigin));
  }

  /** Send the page's reading of the element's clock to the Worker renderer. */
  #postClock(): void {
    this.#worker?.postMessage({
      type: "clock",
      video: this.#workerVideoState(),
      at: performance.now(),
      timeOrigin: performance.timeOrigin,
    } satisfies WorkerCommand);
  }

  /** Take in what the coming refresh needs and put up what belongs on it. */
  #presentPictures(): void {
    const video = this.#video;
    // A Worker renderer is sent its readings, with the time they were made.
    if (!this.#externalHost) this.#observeClock(performance.now());
    const rate = this.#clock.rate;
    // What is drawn now reaches the screen at the next refresh.
    const time = this.#clock.at(this.#gridAt + this.#refreshMs);
    // Held for an event, and not read since.
    if (Number.isNaN(time)) return;
    const revision = this.#playbackRevision;
    this.#feed(time, rate);
    if (this.#frameIsCurrent(revision))
      this.#showDecoded(time, rate, video.paused);
  }

  /**
   * Take in pictures until the history holds the successor of every picture
   * whose outputs are due within the lookahead of `time`, the media time of
   * the refresh being filled.
   */
  #feed(time: number, rate: number): void {
    const revision = this.#playbackRevision;
    const lookahead =
      (LOOKAHEAD_REFRESHES * this.#refreshMs * Math.max(1, rate)) / 1000;
    this.#dropPassed(time);
    for (;;) {
      const next = this.#pending[0];
      if (next === undefined) break;
      // A picture is filtered when its successor is taken in, which is one
      // picture ahead of its own time.
      if (next.timestamp > time + lookahead + next.duration) break;
      // A picture of a new size starts with a new set of outputs.
      if (
        (next.width === this.#width && next.height === this.#height
          ? this.#spareOutputs()
          : OUTPUT_POOL_LENGTH) < this.#outputsFor(next)
      )
        break;
      this.#pending.shift();
      this.#take(next, time, rate);
      if (!this.#frameIsCurrent(revision)) return;
      this.#dropPassed(time);
    }
    // Its successor is late, or there is none: filter it against itself when
    // it is due. It is filtered again if the successor comes after all.
    if (
      !this.#awaiting ||
      this.#awaitingFlushed ||
      this.#pending.length > 0 ||
      this.#spareOutputs() < this.#outputsPerPicture()
    )
      return;
    const newest = this.#held[this.#head]!;
    const hysteresis = (PRESENT_HYSTERESIS_MS * rate) / 1000;
    if (this.#finished || newest.timestamp <= time + hysteresis) {
      this.#emit(true, time, rate);
      this.#awaitingFlushed = true;
    }
  }

  /** Output slots a filtered picture takes. A repeated first field shares the first one's. */
  #outputsPerPicture(): number {
    return this.#doubleRate && !this.#filmLocked ? 2 : 1;
  }

  /** Output slots taking `picture` in can fill. */
  #outputsFor(picture: DecodedPicture): number {
    const woven = !picture.interlaced || !this.#enabled;
    return (this.#awaiting ? this.#outputsPerPicture() : 0) + (woven ? 1 : 0);
  }

  /** Whether an output slot holds nothing still wanted. */
  #slotFree(slot: number): boolean {
    const output = this.#outputs[slot];
    if (output === undefined) return false;
    const presented = this.#presentedPicture;
    if (presented?.kind === "texture" && presented.texture === output.texture)
      return false;
    if (this.#shownStart?.slot === slot || this.#previousStart?.slot === slot)
      return false;
    for (const entry of this.#decodedQueue)
      if (entry.slot === slot) return false;
    return true;
  }

  #spareOutputs(): number {
    let spare = 0;
    for (let slot = 0; slot < this.#outputs.length; slot++)
      if (this.#slotFree(slot)) spare++;
    return spare;
  }

  /** The next free output slot round the ring, or null. */
  #spareSlot(): number | null {
    for (let offset = 1; offset <= OUTPUT_POOL_LENGTH; offset++) {
      const slot = (this.#outputHead + offset) % OUTPUT_POOL_LENGTH;
      if (this.#slotFree(slot)) return slot;
    }
    return null;
  }

  /**
   * Take a decoded picture into the history and filter the picture before it,
   * which has its successor now.
   */
  #take(picture: DecodedPicture, time: number, rate: number): void {
    const newest = this.#taken ? this.#held[this.#head]! : null;
    const end = newest === null ? 0 : newest.timestamp + newest.duration;
    const resized =
      picture.width !== this.#width || picture.height !== this.#height;
    const stale =
      newest === null ||
      resized ||
      picture.timestamp < end - TIMESTAMP_TOLERANCE ||
      picture.timestamp - end > CONTINUOUS_SECONDS;
    const gap = !stale && picture.timestamp - end > TIMESTAMP_TOLERANCE;
    // Shown as it is: one instant, or filtering is off.
    const woven = !picture.interlaced || !this.#enabled;
    const awaiting = this.#awaiting;
    const flushed = this.#awaitingFlushed;
    this.#awaiting = false;
    this.#awaitingFlushed = false;
    // The waiting picture's successor is not its neighbour, so it is filtered
    // against itself. A new size throws its outputs away anyway.
    if (awaiting && !flushed && (stale || woven) && !resized)
      this.#emit(true, time, rate);
    if (stale) {
      if (newest !== null) this.#stats.discontinuities++;
      this.#frames = 0;
      this.#resetFieldMetrics();
      this.#filmHold = 0;
    } else if (
      newest !== null &&
      !woven &&
      newest.interlaced &&
      newest.topFieldFirst !== picture.topFieldFirst
    ) {
      // Detection measured under the other field order does not carry over.
      this.#resetFieldMetrics(true);
    }
    const at = performance.now();
    this.#restartReportAfterIdle(at);
    this.#lastFrameAt = at;
    const revision = this.#playbackRevision;
    const q = this.#beginGpuTimer(false);
    try {
      if (resized) {
        this.#resize(picture.width, picture.height);
        if (this.#outputs.length !== OUTPUT_POOL_LENGTH)
          throw new Error("decoded pictures have no output textures");
      }
      this.#upload(picture);
    } catch (error) {
      this.#endGpuTimer(q);
      this.#notifyFailure(
        error instanceof Error ? error.message : String(error),
      );
      this.stop();
      return;
    } finally {
      this.#release(picture.data);
    }
    if (woven) {
      if (!picture.interlaced) {
        // As for a progressive stretch of the element's pictures.
        if (this.#filmHold > 0) this.#filmHold--;
        this.#afterProgressive = true;
      }
      this.#emitWoven();
      // Not a neighbour for the filter.
      this.#frames = 0;
    } else {
      if (awaiting && !stale) {
        const current = this.#held[(this.#head + HISTORY - 1) % HISTORY]!;
        this.#fieldOrder = current.topFieldFirst;
        this.#ensureFilm();
        if (this.#frameIsCurrent(revision))
          this.#measurePhase(
            gap ? 1 : 0,
            Math.round(current.timestamp * 1000),
            this.#doubleRate,
          );
        if (this.#frameIsCurrent(revision)) this.#emit(false, time, rate);
      } else {
        this.#gapBehind = gap;
      }
      this.#afterProgressive = false;
      this.#awaiting = true;
    }
    if (!this.#frameIsCurrent(revision)) {
      if (!this.#destroyed) this.#endGpuTimer(q);
      return;
    }
    this.#endGpuTimer(q);
    this.#renderMsSinceReport += performance.now() - at;
    this.#renderFramesSinceReport++;
    this.#report(at);
  }

  /** Convert a decoded picture into the next history slot. */
  #upload(picture: DecodedPicture): void {
    this.#head = (this.#head + 1) % HISTORY;
    this.#converter!.convert(picture, this.#textures[this.#head]!);
    const held = this.#held[this.#head]!;
    held.timestamp = picture.timestamp;
    held.duration = picture.duration;
    held.interlaced = picture.interlaced;
    held.topFieldFirst = picture.topFieldFirst;
    held.repeatFirstField = picture.repeatFirstField;
    this.#frames = Math.min(this.#frames + 1, HISTORY);
    this.#taken = true;
  }

  /** Queue the newest picture as it is, both fields woven. */
  #emitWoven(): void {
    const picture = this.#held[this.#head]!;
    const slot = this.#spareSlot();
    if (slot === null) {
      this.#stats.late++;
      return;
    }
    this.#outputHead = slot;
    // History textures hold rows from the top and outputs from the bottom.
    this.#blitTexture(
      this.#textures[this.#head]!,
      true,
      this.#outputs[slot]!.framebuffer,
    );
    this.#decodedQueue.push({
      slot,
      time: picture.timestamp,
      picture: picture.timestamp,
      end: picture.timestamp + picture.duration,
      start: true,
      scan: decodedScan(picture),
    });
  }

  /**
   * Filter the waiting picture into its outputs: against its successor, or
   * against itself with `flush`. Each output is queued at its own media time:
   * a field at its field's time, a film frame at its place in the film
   * cadence, one picture a frame at the first field's time.
   */
  #emit(flush: boolean, time: number, rate: number): void {
    const picture =
      this.#held[flush ? this.#head : (this.#head + HISTORY - 1) % HISTORY]!;
    // Outputs it was given while its successor was late are replaced.
    const queue = this.#decodedQueue;
    while (queue.length > 0 && queue.at(-1)!.picture === picture.timestamp)
      queue.pop();
    this.#fieldOrder = picture.topFieldFirst;
    // When the next output is due: the successor's first, or never, as far
    // as is known, for a picture filtered against itself.
    const next = flush
      ? Number.POSITIVE_INFINITY
      : this.#held[this.#head]!.timestamp;
    const scan = decodedScan(picture);
    const end = picture.timestamp + picture.duration;
    let queued = false;
    if (this.#filmLocked && !flush) {
      const phase = this.#phase.phase;
      if (phase === FILM_DUPLICATE_PHASE) {
        this.#filmDropped++;
        return;
      }
      const at = picture.timestamp + (FILM_LEAD[phase] ?? 0) * picture.duration;
      queued =
        this.#output(
          at,
          at + (picture.duration * PULLDOWN_FRAMES) / FILM_FRAMES,
          next,
          picture.timestamp,
          end,
          true,
          false,
          null,
          flush,
          scan,
          time,
          rate,
        ) !== null;
    } else if (!this.#doubleRate) {
      queued =
        this.#output(
          picture.timestamp,
          next,
          next,
          picture.timestamp,
          end,
          true,
          false,
          null,
          flush,
          scan,
          time,
          rate,
        ) !== null;
    } else {
      // A repeated first field is the first field again, a third of the
      // picture's time after the second.
      const fields = picture.repeatFirstField ? 3 : 2;
      const step = picture.duration / fields;
      let first: number | null = null;
      for (let field = 0; field < fields; field++) {
        const at = picture.timestamp + field * step;
        const slot = this.#output(
          at,
          field + 1 < fields ? at + step : next,
          next,
          picture.timestamp,
          end,
          field === 0,
          field === 1,
          field === 2 ? first : null,
          flush,
          scan,
          time,
          rate,
        );
        if (field === 0) first = slot;
        if (slot !== null) queued = true;
      }
    }
    if (!queued && next <= time) this.#countMissed(end);
  }

  /**
   * Filter one output into a slot and queue it for `at`, unless it can never
   * be shown. `until` is when the output after it is due and `pictureUntil`
   * when the next picture is; `picture` and `pictureEnd` are the picture's
   * own time and end. `slot` is a slot already holding the same field.
   * Returns the slot, or null.
   */
  #output(
    at: number,
    until: number,
    pictureUntil: number,
    picture: number,
    pictureEnd: number,
    start: boolean,
    second: boolean,
    slot: number | null,
    flush: boolean,
    scan: Scan,
    time: number,
    rate: number,
  ): number | null {
    if (!this.#useful(at, until, pictureUntil, time, rate)) {
      if (this.#wasDue(until)) this.#stats.late++;
      return null;
    }
    if (slot === null) {
      slot = this.#spareSlot();
      if (slot === null) {
        this.#stats.late++;
        return null;
      }
      this.#outputHead = slot;
      this.#render(flush, second, this.#outputs[slot]!.framebuffer);
    }
    this.#decodedQueue.push({
      slot,
      time: at,
      picture,
      // A film frame is due past the time of the picture after it.
      end: Number.isFinite(pictureUntil)
        ? Math.max(until, pictureUntil)
        : pictureEnd,
      start,
      scan,
    });
    return slot;
  }

  /**
   * Whether an output due from `at` until `until` can be shown. A refresh
   * shows the newest output due by then, so one whose successor is due before
   * the next refresh after `at` is never seen: at rates the display cannot
   * keep up with, or after it was due. Refreshes are predicted from `time`,
   * the media time of the coming one, with a margin for the hysteresis.
   * While the clock stands still every output of a current picture is kept,
   * since a paused element shows its picture's first field.
   */
  #useful(
    at: number,
    until: number,
    pictureUntil: number,
    time: number,
    rate: number,
  ): boolean {
    if (rate === 0) return pictureUntil > time;
    const margin = (2 * PRESENT_HYSTERESIS_MS * rate) / 1000;
    if (until <= time - margin) return false;
    const refresh = (this.#refreshMs * rate) / 1000;
    if (until - at + 2 * margin >= refresh) return true;
    const refreshes = Math.max(0, Math.ceil((at - margin - time) / refresh));
    return time + refreshes * refresh < until + margin;
  }

  /**
   * Put up the output the coming refresh should show.
   *
   * Playing, that is the newest output due by `time`. Where an output's time
   * is within the hysteresis of `time`, the refresh advances by as many
   * outputs as the last one did if it can, so that the one slip a field rate
   * the refresh does not divide into must make happens once rather than
   * flapping. Paused, it is the first output of the picture `time` falls in.
   */
  #showDecoded(time: number, rate: number, paused: boolean): void {
    const queue = this.#decodedQueue;
    // Pictures a jump of the position left behind do not go up: the canvas
    // keeps what it shows until a picture of the new position is there.
    let behind = 0;
    while (behind < queue.length && !this.#wasDue(queue[behind]!.end)) behind++;
    if (behind > 0) queue.splice(0, behind);
    let index = -1;
    if (paused) {
      for (let i = 0; i < queue.length && queue[i]!.picture <= time; i++)
        if (queue[i]!.start) index = i;
      if (index < 0) {
        // The picture is one already shown.
        const current = this.#shownStart;
        const previous = this.#previousStart;
        let start =
          current !== null && current.picture <= time ? current : null;
        if (
          previous !== null &&
          previous.picture <= time &&
          (start === null || previous.picture > start.picture)
        )
          start = previous;
        if (start !== null && start !== this.#shownOutput)
          this.#showOutput(start);
        return;
      }
      this.#advanced = 1;
    } else {
      // Outputs already shown in an earlier version, filtered against
      // themselves while their successor was late.
      let replaced = 0;
      while (
        replaced < queue.length &&
        queue[replaced]!.time <= this.#shownTime
      )
        replaced++;
      const hysteresis = (PRESENT_HYSTERESIS_MS * rate) / 1000;
      let due = 0;
      let near = 0;
      for (let i = replaced; i < queue.length; i++) {
        const slack = time - queue[i]!.time;
        if (slack >= hysteresis) due++;
        else if (slack >= -hysteresis) near++;
        else break;
      }
      const count = Math.min(Math.max(this.#advanced, due), due + near);
      this.#advanced = count;
      if (count === 0) {
        queue.splice(0, replaced);
        return;
      }
      index = replaced + count - 1;
      // Each output passed over was due until the one after it.
      for (let i = replaced; i < index; i++)
        if (this.#wasDue(queue[i + 1]!.time)) this.#stats.late++;
    }
    const entry = queue[index]!;
    queue.splice(0, index + 1);
    this.#showOutput(entry);
  }

  #showOutput(entry: DecodedOutput): void {
    const begin = performance.now();
    const q = this.#beginGpuTimer(true);
    this.#show(entry.slot);
    this.#endGpuTimer(q);
    this.#showMsSinceReport += performance.now() - begin;
    this.#showFramesSinceReport++;
    this.#shownOutput = entry;
    this.#shownTime = entry.time;
    if (entry === this.#shownStart || entry === this.#previousStart) return;
    if (entry.start || this.#shownStart?.picture !== entry.picture) {
      this.#previousStart = this.#shownStart;
      this.#shownStart = entry.start ? entry : null;
    }
  }

  /** Take one input into the shared history and decide its YADIF or IVTC presentation. */
  #processFrame(now: DOMHighResTimeStamp, metadata: FrameObservation): void {
    const revision = this.#playbackRevision;
    if (!this.#frameIsCurrent(revision)) return;
    this.#selectVideoState(metadata.mediaTime);
    if (!this.#frameIsCurrent(revision)) return;
    if (metadata.width > 0 && metadata.height > 0) {
      // Chromium can submit the destination frame while `seeking` is still
      // true, immediately before `seeked`. Remember that this frame already
      // belongs to the new playhead so the event does not hide it again.
      let seekFrame = false;
      if (!this.#seekFrameReady && this.#video.seeking) {
        const buffered = this.#video.buffered;
        // mediaTime is the start of the frame containing the playhead, so it
        // may precede currentTime by one measured frame period.
        const frameSeconds =
          this.#periodMs >= MIN_PERIOD_MS
            ? this.#periodMs / 1000
            : MAX_PERIOD_MS / 1000;
        for (let index = 0; index < buffered.length; index++) {
          if (
            metadata.mediaTime >= buffered.start(index) &&
            metadata.mediaTime < buffered.end(index) &&
            Math.abs(metadata.mediaTime - this.#video.currentTime) <=
              frameSeconds
          ) {
            seekFrame = true;
            break;
          }
        }
      }
      if (seekFrame) this.#seekFrameReady = true;
      // Standalone users do not have a container feeding coded sizes. Their
      // callback dimensions remain the best available fallback.
      if (this.#width === 0 || this.#height === 0)
        this.#resize(metadata.width, metadata.height);
      if (!this.#frameIsCurrent(revision)) return;
      if (this.#scan && !this.#scan.interlaced) {
        // A progressive picture goes up as it is, but it is output all the
        // same and has to be reported. Soft-telecined film is exactly this --
        // 24 progressive pictures a second between short hard-telecined runs
        // -- and without a report here the rate of the last interlaced run,
        // doubled or averaged with the film around it, stayed on show for as
        // long as the progressive stretch lasted.
        const at = performance.now();
        this.#restartReportAfterIdle(at);
        this.#lastFrameAt = at;
        // Soft and hard telecine alternate within film. A short progressive
        // stretch does not end the hold. A long one runs it down.
        if (this.#filmHold > 0) this.#filmHold--;
        this.#afterProgressive = true;
        this.#showVideo();
        this.#renderMsSinceReport += performance.now() - at;
        this.#renderFramesSinceReport++;
        this.#showFramesSinceReport++;
        this.#report(at);
        return;
      }
      // A seek, or a stream that starts again somewhere else, leaves the held
      // frames belonging to a different moment. Timing says so before any
      // event does, and playback that merely dropped a frame is left alone:
      // the neighbours are then further apart than they should be, which is
      // worth less than filtering nothing at all.
      const elapsed = metadata.mediaTime - this.#lastMediaTime;
      // On Firefox, VideoFrames supplies its own discontinuity signal and
      // wall-clock cadence. The coarse media clock still guards the path: a
      // forward media-time jump that keeps painting smoothly (MSE splice,
      // live gap) is exactly the discontinuity VideoFrames cannot see.
      const mozTiming = metadata.mozTiming;
      const stale =
        seekFrame ||
        (mozTiming
          ? mozTiming.discontinuity ||
            elapsed < 0 ||
            elapsed > CONTINUOUS_SECONDS
          : elapsed < 0 || elapsed > CONTINUOUS_SECONDS);
      if (stale) {
        this.#frames = 0;
        this.#periodMs = 0;
        this.#stats.discontinuities++;
        // The fields still waiting stand for moments the element has left
        // behind, and the clock they were timed by is pinned to the same
        // place. Both start again from where playback actually is.
        this.#dropQueue();
        this.#resetFieldMetrics();
        // The stream after a discontinuity need not be film, so the hold ends.
        // Exception: after a progressive stretch. No media time is kept
        // through one, so the next frame always looks like a jump, and the
        // stretch has already run the hold down.
        if (seekFrame || !this.#afterProgressive) this.#filmHold = 0;
      }
      this.#afterProgressive = false;
      const missed = this.#count(metadata.presentedFrames, stale);
      // The same picture presented again, which the compositor does whenever
      // nothing new has been decoded: paused, stalled, or stopped at the end
      // of a stream, and at the display's rate rather than the video's.
      // Filtering it again would spend a frame's work on a canvas that
      // already holds the answer, and taking it into the ring would leave the
      // filter holding one moment twice over and calling it motion.
      // On the Firefox path mediaTime is the coarse media clock and repeats
      // across distinct pictures, so only a repeated frame count means the
      // same picture presented again.
      if (
        this.#frames > 0 &&
        metadata.mediaTime === this.#lastMediaTime &&
        (!mozTiming || metadata.presentedFrames === this.#lastPresentedFrames)
      ) {
        return;
      }
      if (!stale) {
        const mozPeriodMs = mozTiming?.periodMs ?? 0;
        // #measure takes media seconds and divides by the rate to reach wall
        // time; mozTiming is already wall-clock ms, so scale it back up.
        if (mozPeriodMs > 0)
          this.#measure(
            (mozPeriodMs * (this.#video.playbackRate || 1)) / 1000,
            1,
          );
        else if (this.#frames > 0 && elapsed > 0)
          this.#measure(elapsed, missed + 1);
      }
      this.#lastMediaTime = metadata.mediaTime;
      this.#lastPresentedFrames = metadata.presentedFrames;
      const at = performance.now();
      this.#restartReportAfterIdle(at);
      this.#lastFrameAt = at;
      const begin = performance.now();
      const q = this.#beginGpuTimer(false);
      this.#push();
      this.#ensureFilm();
      if (!this.#frameIsCurrent(revision)) {
        if (!this.#destroyed) this.#endGpuTimer(q);
        return;
      }
      this.#measurePhase(
        missed,
        metadata.presentedFrames,
        this.#doubleRate && this.#scheduling(),
      );
      if (!this.#frameIsCurrent(revision)) {
        if (!this.#destroyed) this.#endGpuTimer(q);
        return;
      }
      // Timed from when the frame reaches the screen, which unlike `now`
      // does not move when the callback runs late; a refresh of margin
      // covers a late callback. (otya) Worker rendering keeps the same
      // anchor: the metadata says which clock its display time was measured
      // against, so it converts rather than being replaced by an arrival
      // time that carries the transit across the thread boundary with it.
      const frameAt = this.#displayTime(metadata, now);
      const shown = frameAt + this.#refreshMs;
      if (this.#filmLocked) {
        // Reconstruct film through the shared queue using the detector's field metrics.
        if (this.#scheduling()) {
          const phase = this.#phase.phase;
          if (phase === FILM_DUPLICATE_PHASE) {
            this.#filmDropped++;
            this.#droppedBefore++;
            // The repeated frame contributes no output picture.
          } else {
            const duration = (this.#periodMs * PULLDOWN_FRAMES) / FILM_FRAMES;
            const queueResetted = this.#prepareQueue(1, now, duration);
            // Phase 2 is whole only once the frame after it has arrived; the
            // others are held back to match, so the film frames come out 1.25
            // periods apart. (otya FILM_LEAD)
            const lead = FILM_LEAD[phase] ?? 0;
            const ideal =
              queueResetted || this.#lastScheduled === null
                ? shown + duration
                : shown + lead * this.#periodMs;
            this.#filter(
              "film",
              false,
              this.#schedule("film", ideal, duration),
              duration,
            );
          }
        } else {
          this.#render(false, false, null);
        }
      } else if (this.#doubleRate && this.#scheduling()) {
        const duration = this.#periodMs / 2;
        const queueResetted = this.#prepareQueue(2, now, duration);
        // One field interval of slack lets the first output survive when the
        // video callback runs just after the animation callback for the same
        // composite. Without it, both fields are due at the next animation
        // callback and the scheduler retires the first one before drawing it.
        // As in the film path, the slack applies only when no chain exists.
        const ideal =
          queueResetted || this.#lastScheduled === null
            ? shown + duration * 2
            : shown;
        const at = this.#schedule("field", ideal, duration);
        this.#filter("field", false, at, duration);
        this.#filter("field", true, at + duration, duration);
      } else if (this.#scheduling()) {
        // Ordinary frames go through the same drift-corrected chain (otya
        // "frame" cadence) instead of bypassing the schedule: paced,
        // drift-corrected presentation with the loop running. Only when the
        // loop is off do pictures go straight to the canvas.
        const duration = this.#periodMs;
        const queueResetted = this.#prepareQueue(1, now, duration);
        const frameIdeal =
          queueResetted || this.#lastScheduled === null
            ? shown + duration
            : shown;
        // A saturated output pool leaves no slot to queue into; drawing
        // straight to the canvas keeps a picture for now instead of holding
        // the previous one with no count (G1).
        const queued = this.#filter(
          "frame",
          false,
          this.#schedule("frame", frameIdeal, duration),
          duration,
        );
        if (!queued) {
          this.#stats.late++;
          this.#render(false, false, null);
        }
      } else {
        // Direct video output supersedes any older film pictures that still
        // have future deadlines in the shared presentation queue.
        this.#stats.late += this.#queue.length;
        this.#dropQueue();
        this.#render(false, false, null);
      }
      this.#reportMaxQueuedFields = Math.max(
        this.#reportMaxQueuedFields,
        this.#queue.length,
      );
      this.#endGpuTimer(q);
      this.#renderMsSinceReport += performance.now() - begin;
      this.#renderFramesSinceReport++;
      this.#report(at);
    }
  }

  /** Rebuild the detector a retry point stood the engine back up for. */
  #ensureFilm(): void {
    if (this.#film && !this.#filmDegraded && !this.#detector) {
      // A retry point stood the engine back up; rebuild the detector the
      // setter would have built. A repeated failure degrades as a new
      // episode rather than silently idling without pulldown detection.
      try {
        this.#ensureDetector();
      } catch (error) {
        this.#degradeFilm(
          `film detector unavailable: ${error instanceof Error ? error.message : String(error)}`,
        );
      }
    }
  }

  /**
   * Run the pulldown detection for the frame behind the newest, which is the
   * one about to be filtered. `missed` is how many frames went unseen before
   * the newest, `frame` labels the debug overlay, and `secondFields` is
   * whether the frame's second field is drawn too.
   */
  #measurePhase(missed: number, frame: number, secondFields: boolean): void {
    this.#measured = false;
    this.#matching = false;
    this.#aheadMeasured = false;
    if (this.#film && !this.#filmDegraded) {
      // GPU pulldown detection (otya): a missed frame leaves a gap in the
      // held frames, so the comparisons carried over would be between
      // frames that were never neighbours.
      let measured = false;
      if (this.#frames === HISTORY && missed === 0) {
        try {
          this.#collectPhase();
          this.#detect();
          measured = true;
        } catch (error) {
          // A GPU failure must not stop the frame loop (e.g. an
          // incomplete RGBA32F framebuffer despite the extension being
          // present). The engine stands down with notification -- the
          // `film` option stays on, so this is not a silent fallback --
          // and a retry point attempts the GPU path again.
          this.#degradeFilm(
            `film detection failed: ${error instanceof Error ? error.message : String(error)}`,
          );
        }
      } else {
        this.#resetFieldMetrics(true);
      }
      this.#phaseCounts[this.#phase.phase] =
        (this.#phaseCounts[this.#phase.phase] ?? 0) + 1;
      this.#filmLocked =
        this.#phase.phase !== 0 && this.#phase.run >= FILM_LOCK_FRAMES;
      if (this.#filmLocked) this.#filmHold = FILM_HOLD_FRAMES;
      else if (this.#filmHold > 0) this.#filmHold--;
      // While the cadence is held, the filter weaves by its phase. Matching
      // then only covers frames for which the loss of the cadence is read
      // back late. The counts are for this frame and the frames on either
      // side of it. They do not apply to a frame that was not measured, or
      // to one whose previous frame is not its neighbour. The frame after a
      // gap is measured against the frame from before the gap.
      this.#measured = measured && !this.#gapBehind;
      this.#matching = this.#measured && this.#filmHold > 0;
      // Counts for the next frame are needed only when a second field is
      // drawn (field path only) and matching runs without a lock, because
      // only that case looks beyond the frame's own fields.
      this.#aheadMeasured =
        this.#matching &&
        !this.#filmLocked &&
        secondFields &&
        this.#measureAhead();
      if (this.#matching && !this.#filmLocked) this.#stats.matched++;
      if (this.#debug) this.#debugText = this.#describePhase(frame);
    }
    this.#gapBehind = missed > 0;
  }

  #frameIsCurrent(revision: number): boolean {
    return (
      !this.#destroyed && this.#running && revision === this.#playbackRevision
    );
  }

  #selectVideoState(mediaTime: number): void {
    const revision = this.#playbackRevision;
    let selected: VideoState | undefined;
    for (let index = this.#videoTimeline.length - 1; index >= 0; index--) {
      const state = this.#videoTimeline[index]!;
      if (state.start <= mediaTime + 1e-6) {
        selected = state;
        break;
      }
    }
    // An init reaches the SourceBuffer before its first sample. Applying the
    // size here keeps the texture change on that sample's frame callback.
    if (
      selected?.codedSize &&
      (selected.codedSize.width !== this.#width ||
        selected.codedSize.height !== this.#height)
    )
      this.#resize(selected.codedSize.width, selected.codedSize.height);
    if (!this.#frameIsCurrent(revision)) return;
    const scan = selected?.scan;
    if (
      !scan ||
      (this.#scan?.interlaced === scan.interlaced &&
        this.#scan.topFieldFirst === scan.topFieldFirst)
    )
      return;
    const previousInterlaced = this.#scan?.interlaced;
    this.#scan = scan;
    this.#frames = 0;
    this.#dropQueue();
    // A new section reallocates resources and retries film detection.
    if (!this.#recoverFilm()) return;
    // Progressive sections provide no cadence measurement, and a discontinuity
    // may change the input rate, so remeasure the next interlaced section
    if (previousInterlaced !== scan.interlaced) this.#periodMs = 0;
    if (
      scan.interlaced &&
      (this.#externalHost || this.#workerState === "main")
    ) {
      this.#startLoop();
    } else {
      this.#stopLoop();
    }
    this.#resetFieldMetrics();
  }

  /**
   * Whether pictures are being filtered ahead of time and queued, rather than
   * drawn as their frame arrives.
   *
   * A picture for every frame has nothing to schedule -- there is one of them
   * and it goes up now -- and neither has a filter that has yet to see two
   * frames go by, since until then there is no idea how long a frame lasts.
   */
  #scheduling(): boolean {
    return (
      (this.#doubleRate || this.#film) &&
      this.#periodMs > 0 &&
      this.#outputs.length === OUTPUT_POOL_LENGTH
    );
  }

  /**
   * How long a frame lasts in wall time, kept as a smoothed estimate.
   *
   * Taken from the frames themselves rather than from a frame rate nobody
   * reports, and in wall time, so a rate other than 1 moves the fields with
   * it. A frame the callback never saw makes the step between two of them a
   * whole multiple of the period, and dividing that back out matters: taken
   * at face value, one missed frame would put every field of the next one
   * half a frame late and hold the picture through a refresh it should have
   * moved in.
   */
  #measure(elapsed: number, observedFrames: number): void {
    const step = (elapsed * 1000) / (this.#video.playbackRate || 1);
    // Inferring the frame count from the previous period can perpetuate an incorrectly short estimate.
    const period = step / observedFrames;
    if (period < MIN_PERIOD_MS || period > MAX_PERIOD_MS) return;
    // A much shorter period means the estimate was a multiple of it.
    this.#periodMs =
      this.#periodMs > 0 && period > this.#periodMs * PERIOD_SHORTER
        ? this.#periodMs + (period - this.#periodMs) * PERIOD_SMOOTHING
        : period;
  }

  /**
   * Filter one field into an output texture and put it in the queue.
   *
   * The three frames the filter reads are only the right three between one
   * frame arriving and the next, so both fields of a frame are built here and
   * held as pictures. What is queued after that is a copy waiting for a
   * moment, which no later frame can take away.
   */
  #filter(
    cadence: Cadence,
    second: boolean,
    at: number,
    duration: number,
  ): boolean {
    const slot = this.#nextOutputSlot();
    if (slot === null) return false;
    const output = this.#outputs[slot];
    if (!output) return false;
    this.#outputHead = slot;
    // Whatever this slot held has been waiting two frames for a turn it never
    // got, and its moment is far enough past that showing it now would be a
    // step backwards. Slots are taken in order, so it can only be the oldest.
    while (this.#queue.length > 0 && this.#queue[0]?.slot === slot) {
      this.#queue.shift();
      this.#stats.late++;
    }
    this.#render(false, second, output.framebuffer);
    const ready: Ready = {
      slot,
      at,
      duration,
      cadence,
      phase:
        cadence === "film"
          ? this.#phase.phase
          : cadence === "field"
            ? second
              ? 2
              : 1
            : 0,
      droppedBefore: this.#droppedBefore,
    };
    this.#droppedBefore = 0;
    this.#queue.push(ready);
    this.#lastScheduled = ready;
    return true;
  }

  /**
   * When a picture goes up: one duration after the last one of its cadence,
   * nudged towards the clock by a fraction of the gap so that the schedule
   * follows it without a picture ever moving across a refresh. (otya)
   *
   * `ideal` is when this frame would go up if it were the only one. Frames
   * do not arrive evenly. Where the frame period and the refresh nearly
   * divide, a frame arrives a refresh early or late now and then, and for
   * seconds at a time while the two drift past each other. An early frame is
   * harmless because its pictures wait. A late frame has missed its moment,
   * so the chain restarts from where the frame is. That costs a refresh with
   * nothing new to show, which cannot be avoided. The cost should be paid
   * only once. The frames after it arrive on time, which now counts as a
   * refresh early, and pulling the chain back to them would skip a picture to
   * undo a delay nobody sees. So the chain keeps the lateness it was pushed
   * to (`#scheduleLag`), treats frames that arrive at that phase as on time,
   * and puts frames that are late by no more than the lag covers on the chain.
   *
   * Frames arrive on refreshes. At whatever phase a frame arrives, the
   * remainder of its distance from the chain after removing whole refreshes
   * is the chain's own drift against the refresh grid, and each frame
   * corrects part of it. The lag is kept in whole refreshes for the same
   * reason. A chain held half a refresh off the grid makes each pair of
   * fields come due together, and one of each pair is dropped.
   *
   * The lag follows what frames actually do. If no frame arrives at the
   * lag's phase within SCHEDULE_WINDOW pictures, the lag moves to the nearest
   * phase they did arrive at. If that phase is earlier than the chain allows
   * for, the chain moves up to it, which skips one picture. A frame more than
   * a refresh off on either side is not jitter, and the chain restarts from
   * the clock.
   */
  #schedule(cadence: Cadence, ideal: number, duration: number): number {
    // A non-positive duration cannot anchor a chain; schedule at the ideal
    // instead of resyncing on every picture (G1).
    if (!(duration > 0)) return ideal;
    const last = this.#lastScheduled;
    const refresh = this.#refreshMs;
    if (last !== null && last.cadence === cadence) {
      const chain = last.at + last.duration;
      // `wait` is how long after its own moment the picture goes up on the
      // chain. `refreshes` is that in whole refreshes, `phase` is the part
      // beyond the lag the chain holds on purpose, and `drift` is the
      // remainder: the chain's drift against the grid.
      const wait = chain - ideal;
      const refreshes = Math.round(wait / refresh);
      const phase = refreshes - this.#scheduleLag;
      const drift = wait - refreshes * refresh;
      if (refreshes >= 0 && phase <= 1) {
        const at =
          chain +
          Math.max(
            -DRIFT_STEP_MS,
            Math.min(DRIFT_STEP_MS, -drift * DRIFT_GAIN),
          );
        if (phase === 0) {
          this.#offPhase = 0;
          return at;
        }
        // Early, or late by no more than the lag covers: it goes up on the
        // chain. One such frame does not show where frames arrive.
        if (this.#offPhase === 0 || phase > 0 !== this.#offPhaseNearest > 0) {
          this.#offPhase = 0;
          this.#offPhaseNearest = phase;
        } else if (Math.abs(phase) < Math.abs(this.#offPhaseNearest)) {
          this.#offPhaseNearest = phase;
        }
        if (++this.#offPhase < SCHEDULE_WINDOW) return at;
        const nearest = this.#offPhaseNearest;
        this.#offPhase = 0;
        if (nearest < 0) {
          // Every frame was later than the lag's phase but still in time, so
          // the lag is larger than needed. The chain itself is in place.
          this.#scheduleLag += nearest;
          return at;
        }
        // Every frame was early: the chain runs later than any frame needs.
        this.#stats.resynced++;
        return this.#restart(at - nearest * refresh);
      }
      if (refreshes < 0 && this.#scheduleLag - refreshes <= 1) {
        // The frame is a refresh late against the phase the chain allowed for.
        this.#scheduleLag -= refreshes;
        this.#offPhase = 0;
        this.#stats.resynced++;
        return this.#restart(ideal);
      }
    }
    this.#scheduleLag = 0;
    this.#offPhase = 0;
    if (last !== null) this.#stats.resynced++;
    return this.#restart(ideal);
  }

  /** Start the chain again at `at`, which is where the caller's picture goes. */
  #restart(at: number): number {
    // Pictures queued after the new moment would never be shown in order.
    for (let tail = this.#queue.at(-1); tail && tail.at >= at;) {
      this.#queue.pop();
      this.#stats.late++;
      tail = this.#queue.at(-1);
    }
    return at;
  }

  /** Make room without treating ordinary capacity pressure as clock divergence. */
  #prepareQueue(
    requiredOutputs: number,
    now: number,
    outputDuration: number,
  ): boolean {
    const last = this.#queue.at(-1);
    const maximumUsefulLead =
      (FIELD_QUEUE_LENGTH + 1) * Math.max(this.#refreshMs, outputDuration);
    if (last && last.at - now > maximumUsefulLead) {
      this.#dropQueue();
      this.#stats.queueResetted++;
      return true;
    }

    const overflow = Math.max(
      0,
      this.#queue.length + requiredOutputs - FIELD_QUEUE_LENGTH,
    );
    let retiredDuration = 0;
    let retired = 0;
    while (retired < overflow) {
      const ready = this.#queue.shift();
      if (!ready) break;
      retiredDuration += ready.duration;
      retired++;
    }
    // The retired pictures no longer occupy presentation moments. Close those
    // holes as well as freeing their slots, so the remaining queue stays on the
    // current presentation opportunity under sustained capacity pressure.
    for (const ready of this.#queue) ready.at -= retiredDuration;
    this.#stats.late += retired;
    return false;
  }

  /** Select an output whose pixels are not still represented by the canvas or queue. */
  #nextOutputSlot(): number | null {
    const shownTexture =
      this.#presentedPicture?.kind === "texture"
        ? this.#presentedPicture.texture
        : null;
    const queuedSlots = new Set(this.#queue.map(({ slot }) => slot));
    for (let offset = 1; offset <= OUTPUT_POOL_LENGTH; offset++) {
      const slot = (this.#outputHead + offset) % OUTPUT_POOL_LENGTH;
      const output = this.#outputs[slot];
      if (output && output.texture !== shownTexture && !queuedSlots.has(slot))
        return slot;
    }

    // The pool is saturated: keep the picture represented by the canvas for
    // capture, but retire the oldest queued picture for this newer field. The
    // caller's existing overflow handling accounts for that picture as late.
    const oldest = this.#queue[0];
    if (oldest) {
      const output = this.#outputs[oldest.slot];
      if (output && output.texture !== shownTexture) return oldest.slot;
    }
    return null;
  }

  /** The loop that puts filtered fields up, and the only thing that draws. */
  #startLoop(): void {
    if (this.#loopRequest !== null) return;
    if (!this.#running || this.#lost) return;
    this.#lastLoopAt = 0;
    this.#loopRequest = this.#armAnimationFrame(this.#onLoop);
  }

  #stopLoop(): void {
    this.#cancelAnimationRequest(this.#loopRequest);
    this.#loopRequest = null;
    this.#dropQueue();
  }

  #onLoop = (now: DOMHighResTimeStamp): void => {
    this.#loopRequest = null;
    if (!this.#running || this.#lost) return;
    this.#measureRefresh(now);
    const revision = this.#playbackRevision;
    if (this.#decoded) {
      if (this.#externalHost || this.#workerState === "main")
        this.#presentPictures();
      else this.#postClock();
    } else {
      this.#videoFrames.flush(now);
      if (!this.#frameIsCurrent(revision)) return;
      if (this.#workerState === "main") this.#present(this.#gridAt, now);
    }
    if (!this.#frameIsCurrent(revision)) return;
    this.#loopRequest = this.#armAnimationFrame(this.#onLoop);
  };

  /**
   * Fit a grid of refreshes (period and phase) to the animation frames. rAF
   * timestamps wander by a millisecond or so, which is more than the
   * nearest-refresh decision in #present can take; the grid is what it
   * compares against. A frame far off the grid restarts it. (otya)
   */
  #measureRefresh(now: number): void {
    const step = now - this.#lastLoopAt;
    this.#lastLoopAt = now;
    const refreshes = Math.max(1, Math.round(step / this.#refreshMs));
    const predicted = this.#gridAt + refreshes * this.#refreshMs;
    const error = now - predicted;
    if (
      this.#gridAt === 0 ||
      step <= 0 ||
      step > MAX_PERIOD_MS ||
      Math.abs(error) > this.#refreshMs / 4
    ) {
      // Coalesced callbacks can have nearly identical timestamps at startup.
      // Keep the refresh margin until a physically plausible interval is observed.
      if (step >= 1 && step <= MAX_PERIOD_MS) this.#refreshMs = step;
      this.#gridAt = now;
      return;
    }
    this.#refreshMs += (error / refreshes) * GRID_PERIOD_GAIN;
    this.#gridAt = predicted + error * GRID_PHASE_GAIN;
  }

  /**
   * Where animation frames come from, and the clock their timestamps carry.
   *
   * For Worker rendering it is the host the Worker entry supplied, whose
   * frames are already this realm's. Otherwise it is the window of the
   * document the canvas is in, which is the window that composites it -- and
   * which a document picture-in-picture window becomes by adopting the
   * element. The element is consulted as well, because the two move together
   * and either may be read first while a move is in progress.
   */
  #animationSource(): { frames: AnimationFrames; origin: number } {
    const externalHost = this.#externalHost;
    if (externalHost)
      return { frames: externalHost, origin: performance.timeOrigin };
    const view =
      this.#displayCanvas.ownerDocument?.defaultView ??
      this.#video.ownerDocument?.defaultView ??
      null;
    return view === null
      ? { frames: moduleAnimationFrames, origin: performance.timeOrigin }
      : { frames: view, origin: view.performance.timeOrigin };
  }

  /**
   * Ask the current source for one frame, on this module's clock.
   *
   * An animation frame is timestamped against the clock of the window that
   * served it, and after an adoption that is not the clock the presentation
   * deadlines are on. The conversion belongs to the request rather than to
   * the callback: the source that was asked is the source that answers, so
   * the origin captured here is the right one however often the owner moves.
   */
  #armAnimationFrame(callback: FrameRequestCallback): AnimationRequest {
    const { frames, origin } = this.#animationSource();
    const handle = frames.requestAnimationFrame((timestamp) =>
      callback(this.#localTime(timestamp, origin)),
    );
    return { frames, handle };
  }

  /** Cancel a pending animation frame through the source that issued it. */
  #cancelAnimationRequest(request: AnimationRequest | null): void {
    request?.frames.cancelAnimationFrame(request.handle);
  }

  /**
   * Follow the window that composites the canvas.
   *
   * A request already outstanding on the previous window is not merely late.
   * A window that has gone hidden serves no animation frames at all, so
   * waiting for that callback to notice the move waits for something that
   * will not happen; and cancelling it anywhere but on that same window
   * leaves it outstanding. Every other thing still being observed -- a frame
   * arriving, a layout, the old window saying it is going away -- re-points
   * both requests instead.
   *
   * Nothing queued moves: presentation deadlines are on this module's clock,
   * which no adoption changes. Only the refresh grid starts again, because a
   * grid describes one compositor and this is a different one.
   */
  #followOwner(): void {
    if (this.#externalHost) return;
    this.#watchOwnerDocument();
    const { frames } = this.#animationSource();
    const loopMoved =
      this.#loopRequest !== null && this.#loopRequest.frames !== frames;
    const captureMoved =
      this.#captureRequest !== null && this.#captureRequest.frames !== frames;
    if (!loopMoved && !captureMoved) return;
    this.#lastLoopAt = 0;
    if (loopMoved) {
      this.#cancelAnimationRequest(this.#loopRequest);
      this.#loopRequest = this.#armAnimationFrame(this.#onLoop);
    }
    if (captureMoved) {
      this.#cancelAnimationRequest(this.#captureRequest);
      this.#captureRequest = this.#armAnimationFrame(this.#onCaptureLoop);
    }
  }

  /** Watch the current document for visibility changes and DOM adoption. */
  #watchOwnerDocument(): void {
    const owner = this.#externalHost
      ? null
      : (this.#displayCanvas.ownerDocument ?? null);
    if (owner === this.#ownerDocument) return;
    this.#ownerDocument?.removeEventListener(
      "visibilitychange",
      this.#onOwnerVisibility,
    );
    this.#ownerDocument = owner;
    owner?.addEventListener("visibilitychange", this.#onOwnerVisibility);
    this.#ownerChanges?.disconnect();
    if (owner)
      this.#ownerChanges?.observe(owner, { childList: true, subtree: true });
  }

  #onOwnerVisibility = (): void => {
    if (!this.#destroyed) this.#followOwner();
  };

  /** Deliver faster-playback captures even when a Worker owns the drawing loop. */
  #startCaptureLoop(): void {
    if (
      this.#externalHost ||
      this.#decoded ||
      this.#captureRequest !== null ||
      !this.#videoFrames.captureDriven ||
      !this.#running ||
      this.#lost
    )
      return;
    this.#captureRequest = this.#armAnimationFrame(this.#onCaptureLoop);
  }

  /** Cancel the page's pending capture delivery. */
  #stopCaptureLoop(): void {
    this.#cancelAnimationRequest(this.#captureRequest);
    this.#captureRequest = null;
  }

  /** Flush captured pictures on the refresh that will present them. */
  #onCaptureLoop = (now: DOMHighResTimeStamp): void => {
    this.#captureRequest = null;
    if (!this.#running || this.#lost) return;
    const revision = this.#playbackRevision;
    this.#videoFrames.flush(now);
    if (this.#frameIsCurrent(revision) && this.#videoFrames.captureDriven)
      this.#captureRequest = this.#armAnimationFrame(this.#onCaptureLoop);
  };

  /**
   * Put up whichever filtered field belongs on the screen next.
   *
   * What is drawn during an animation frame reaches the screen at the composite
   * after it, so that is the moment being filled, and a field goes up at
   * whichever composite falls nearest the moment it stands for -- half a
   * refresh either side of it. Where two of them have come due since the last
   * one, only the newer is shown: a screen has one picture per refresh, and
   * the older of the two is a moment the viewer should already be past.
   *
   * Near the half-refresh boundary a picture goes the way the last one went,
   * so that the slip a cadence the refresh does not divide into must make
   * every so often happens once rather than flapping.
   */
  #present(now: number, frameAt: number): void {
    // `now` is the refresh-grid time, which is the moment being filled: what
    // is drawn during an animation frame reaches the screen at the composite
    // after it, and a field goes up at whichever composite falls nearest the
    // moment it stands for -- half a refresh either side of it. Where two of
    // them have come due since the last one, only the newer is shown: a
    // screen has one picture per refresh, and the older of the two is a
    // moment the viewer should already be past.
    //
    // Near the half-refresh boundary a picture goes the way the last one
    // went, so that the slip a cadence the refresh does not divide into must
    // make every so often happens once rather than flapping. (otya)
    const half = this.#refreshMs / 2;
    const due = (ready: Ready) => {
      const ahead = ready.at - now;
      if (ahead <= half - PRESENT_HYSTERESIS_MS) return true;
      if (ahead > half + PRESENT_HYSTERESIS_MS) return false;
      return this.#shownAhead > 0;
    };
    while (this.#queue[1] && due(this.#queue[1])) {
      this.#stats.late++;
      this.#queue.shift();
    }
    const ready = this.#queue[0];
    if (!ready || !due(ready)) return;
    this.#queue.shift();
    this.#shownAhead = ready.at - now;
    const begin = performance.now();
    const q = this.#beginGpuTimer(true);
    this.#show(ready.slot);
    this.#endGpuTimer(q);
    this.#showMsSinceReport += performance.now() - begin;
    this.#showFramesSinceReport++;
    if (this.#debug) this.#logShown(ready, frameAt);
    this.#shownAt = frameAt;
  }

  /** Preserve upstream's opt-in presentation timing log in either renderer. */
  #logShown(ready: Ready, frameAt: number): void {
    const step = this.#shownAt === 0 ? 0 : frameAt - this.#shownAt;
    const refreshes = step / this.#refreshMs;
    const which =
      ready.cadence === "film"
        ? `phase ${ready.phase}`
        : ready.cadence === "field"
          ? `field ${ready.phase}`
          : "frame";
    const duplicate =
      ready.phase === 0 ? "duplicate" : `phase ${FILM_DUPLICATE_PHASE}`;
    const dropped =
      ready.droppedBefore > 0
        ? `, ${duplicate} dropped before it` +
          (ready.droppedBefore > 1 ? ` (${ready.droppedBefore})` : "")
        : "";
    console.log(
      `yadif: +${step.toFixed(2)} ms (${refreshes.toFixed(2)} refreshes) ${ready.cadence} ${which}, due ${(ready.at - frameAt).toFixed(2)} ms${dropped}`,
    );
  }

  /** Copy one of the filtered pictures onto the canvas. */
  #show(slot: number): void {
    const output = this.#outputs[slot];
    if (!output) return;
    this.#showTexture(output.texture);
  }

  /** Put a progressive frame through unchanged, keeping one display surface. */
  #showVideo(): void {
    this.#push();
    const texture = this.#textures[this.#head];
    if (texture) this.#showTexture(texture, true);
    // Progressive frames are not neighbours of the next interlaced frame.
    this.#frames = 0;
  }

  /** Apply visibility on the page; a Worker reports only the desired state. */
  #setVisible(visible: boolean): void {
    if (this.#externalHost) {
      this.#externalHost.onVisibility(visible);
      return;
    }
    this.#displayCanvas.style.visibility = visible ? "visible" : "hidden";
  }

  #showTexture(texture: WebGLTexture, flip = false, countOutput = true): void {
    this.#blitTexture(texture, flip, null);
    this.#presentedPicture = { kind: "texture", texture, flip };
    this.#setVisible(true);
    if (countOutput) this.#outputSinceReport++;
  }

  /** Copy a texture onto the canvas or into an output. */
  #blitTexture(
    texture: WebGLTexture,
    flip: boolean,
    target: WebGLFramebuffer | null,
  ): void {
    const gl = this.#gl;
    gl.bindFramebuffer(gl.FRAMEBUFFER, target);
    gl.useProgram(this.#blit);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.uniform1i(this.#blitField, 0);
    gl.uniform1i(this.#blitFlip, flip ? 1 : 0);
    gl.viewport(0, 0, this.#width, this.#height);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  /**
   * Account for the frames between this one and the last one seen.
   *
   * There is no event for a frame the callback was not run for; the only sign
   * of one is that the count of frames went up by more than one. That count
   * comes from the compositor where it provides one, and otherwise from
   * VideoFrames. Frames thrown away either side of a discontinuity are not
   * counted: the held frames were being dropped anyway, and a seek presents
   * what it passes over.
   *
   * Returns how many frames were missed between the last one and this one.
   */
  #count(presented: number, stale: boolean): number {
    let missed = 0;
    if (this.#lastPresented !== 0 && !stale) {
      missed = Math.max(0, presented - this.#lastPresented - 1);
      this.#stats.missed += missed;
    }
    this.#lastPresented = presented;
    return missed;
  }

  /**
   * Frames stopped arriving for a while -- a pause, a stall, a tab in the
   * background -- and a rate averaged over time nothing was asked of the
   * filter says nothing about it. Begin the interval at this frame.
   */
  #restartReportAfterIdle(at: number): void {
    if (at - this.#lastFrameAt <= STATS_INTERVAL_MS) return;
    this.#reportedAt = at;
    this.#renderFramesSinceReport = 0;
    this.#renderMsSinceReport = 0;
    this.#showFramesSinceReport = 0;
    this.#showMsSinceReport = 0;
    this.#reportMaxQueuedFields = 0;
    this.#outputSinceReport = 0;
    this.#gpuFrameNanosecondsSinceReport = 0;
    this.#gpuFrameCountSinceReport = 0;
    this.#gpuFieldNanosecondsSinceReport = 0;
    this.#gpuFieldCountSinceReport = 0;
  }

  #report(at: number): void {
    const elapsed = at - this.#reportedAt;
    if (elapsed < STATS_INTERVAL_MS) return;
    const frames =
      !this.#decoded &&
      this.#scheduling() &&
      (this.#doubleRate || this.#filmLocked)
        ? this.#showFramesSinceReport
        : this.#renderFramesSinceReport;
    // Keep the published per-input-picture CPU cost: both fields' filtering
    // and presentation belong to that one input. Output cadence can change
    // (single-rate, double-rate or film); it must not change this denominator.
    const frameMs = this.#renderFramesSinceReport
      ? (this.#renderMsSinceReport + this.#showMsSinceReport) /
        this.#renderFramesSinceReport
      : 0;

    let gpuMs: number | undefined;
    if (this.#timerQueryExtension != null) {
      gpuMs = 0;
      if (this.#gpuFrameCountSinceReport !== 0) {
        gpuMs +=
          this.#gpuFrameNanosecondsSinceReport /
          1_000_000 /
          this.#gpuFrameCountSinceReport;
      }
      if (this.#gpuFieldCountSinceReport !== 0) {
        gpuMs +=
          this.#gpuFieldNanosecondsSinceReport /
          1_000_000 /
          this.#gpuFieldCountSinceReport /
          2;
      }
    }

    const stats: DeinterlaceStats = {
      ...this.#stats,
      // The element's own count of what its decoder could not keep up with,
      // which is the machine being behind rather than this filter.
      dropped: this.#video.getVideoPlaybackQuality?.().droppedVideoFrames ?? 0,
      fps: (frames * 1000) / elapsed,
      frameMs,
      maxQueuedFields: this.#reportMaxQueuedFields,
      outputFps: (this.#outputSinceReport * 1000) / elapsed,
      gpuMs,
      film: this.#filmLocked,
      oneInstant: this.#oneInstant,
      filmError: this.#filmDegraded,
    };
    // Main-thread reports use the same observation paths as worker
    // notifications: DPlayer listens to the event, standalone callers can
    // use the callback supplied at construction time.
    this.dispatchEvent(new CustomEvent("stats", { detail: stats }));
    this.#onStats?.(stats);
    this.#reportedAt = at;
    this.#renderFramesSinceReport = 0;
    this.#renderMsSinceReport = 0;
    this.#showFramesSinceReport = 0;
    this.#showMsSinceReport = 0;
    this.#reportMaxQueuedFields = 0;
    this.#outputSinceReport = 0;
    this.#gpuFrameNanosecondsSinceReport = 0;
    this.#gpuFrameCountSinceReport = 0;
    this.#gpuFieldNanosecondsSinceReport = 0;
    this.#gpuFieldCountSinceReport = 0;
  }

  /** Take the newest frame into the ring. */
  #push(): void {
    const gl = this.#gl;
    this.#head = (this.#head + 1) % HISTORY;
    const staged = this.#stagedPicture;
    const held = this.#textures[this.#head];
    if (staged !== null && this.#pictures !== null && held !== undefined) {
      // The picture is already in a texture, uploaded when it was first
      // seen. The element may show a later picture by now, so that texture
      // replaces this ring slot and the displaced texture goes back to the
      // watch.
      this.#textures[this.#head] = this.#pictures.adopt(staged, held);
      this.#stagedPicture = null;
    } else {
      gl.bindTexture(gl.TEXTURE_2D, held ?? null);
      // texSubImage2D is very slow in WebKit (~7 ms), so use texImage2D instead (~1 ms).
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        this.#frameSource,
      );
    }
    this.#frames = Math.min(this.#frames + 1, HISTORY);
  }

  /**
   * Filter one frame, onto the canvas or into an output texture.
   *
   * A null `target` is the canvas itself, which is where the picture goes when
   * there is one per frame and nothing to schedule. An output framebuffer is a
   * field being kept for its moment.
   *
   * `second` asks for the frame's other field: the same three frames filtered
   * the other way round, keeping the field that came second and rebuilding
   * the first. The shader takes the pair of frames the missing line sits
   * between from the parity, so this is the whole of it.
   *
   * With `film` on, the shader is also given the field metrics, and puts a
   * film frame back together rather than filtering it.
   */
  #render(
    flush: boolean,
    second: boolean,
    target: WebGLFramebuffer | null,
    countOutput = true,
  ): void {
    if (this.#frames === 0 || this.#lost) return;
    if (countOutput) {
      if (this.#frames === HISTORY && !flush) this.#stats.filtered++;
      else this.#stats.degraded++;
    }
    const gl = this.#gl;
    const { prev, cur, next } = this.#neighbours(flush);
    gl.bindFramebuffer(gl.FRAMEBUFFER, target);
    gl.useProgram(this.#program);
    for (const [unit, texture] of [prev, cur, next].entries()) {
      gl.activeTexture(gl.TEXTURE0 + unit);
      gl.bindTexture(gl.TEXTURE_2D, this.#textures[texture] ?? null);
    }
    gl.uniform1i(this.#location.prev, 0);
    gl.uniform1i(this.#location.cur, 1);
    gl.uniform1i(this.#location.next, 2);
    // Use the detector's field metrics while film reconstruction is enabled.
    const metrics = this.#film ? (this.#detector?.texture ?? null) : null;
    const comb = this.#film ? (this.#detector?.combTexture ?? null) : null;
    const film = metrics !== null && comb !== null;
    if (metrics !== null && comb !== null) {
      gl.activeTexture(gl.TEXTURE0 + 3);
      gl.bindTexture(gl.TEXTURE_2D, metrics);
      gl.uniform1i(this.#location.fieldMetrics, 3);
      gl.activeTexture(gl.TEXTURE0 + 4);
      gl.bindTexture(gl.TEXTURE_2D, comb);
      gl.uniform1i(this.#location.comb, 4);
    }
    // The comb counts are for the frame behind the newest and its
    // neighbours, which is not the frame a flush filters. A second field
    // also needs the counts for the following frame.
    const combAhead = this.#aheadMeasured
      ? (this.#detector?.combAheadTexture ?? null)
      : null;
    const drawable = film && !flush;
    gl.activeTexture(gl.TEXTURE0 + 5);
    gl.bindTexture(gl.TEXTURE_2D, combAhead);
    gl.uniform1i(this.#location.combAhead, 5);
    // Texture creation and uploads elsewhere bind on the active unit. Leave
    // it on unit 0, which every draw rebinds.
    gl.activeTexture(gl.TEXTURE0);
    gl.uniform2i(this.#location.size, this.#width, this.#height);
    // The lines that survive are the ones of the field being shown: the first
    // field is the top one when the top field leads, and the second is the
    // other. A frame at a time is always the first.
    const first = this.#topFieldFirst ? 0 : 1;
    gl.uniform1i(this.#location.parity, second ? 1 - first : first);
    gl.uniform1i(this.#location.tff, this.#topFieldFirst ? 1 : 0);
    gl.uniform1i(this.#location.second, second ? 1 : 0);
    gl.uniform1i(this.#location.spatialCheck, this.#spatialCheck ? 1 : 0);
    gl.uniform1i(this.#location.debug, this.#debug ? 1 : 0);
    gl.uniform1i(this.#location.film, film ? 1 : 0);
    gl.uniform1i(
      this.#location.match,
      drawable && this.#matching && (!second || combAhead !== null) ? 1 : 0,
    );
    // The shader reads the one-instant verdict from the detector's metrics
    // itself. This uniform only says that the comb counts it would weave by
    // are those of the frame being drawn.
    gl.uniform1i(this.#location.instant, drawable && this.#measured ? 1 : 0);
    gl.uniform1i(this.#location.phase, this.#phase.phase);
    gl.viewport(0, 0, this.#width, this.#height);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    if (this.#debug && film) this.#drawText(this.#debugText, 0, 90);
    // A picture filtered into a texture is not on the screen yet, and showing
    // the canvas for it would put up whatever was drawn on it last.
    if (target === null) {
      this.#presentedPicture = { kind: "yadif", flush, second };
      this.#setVisible(true);
      if (countOutput) this.#outputSinceReport++;
    }
  }

  #neighbours(flush: boolean): { prev: number; cur: number; next: number } {
    const back = (frames: number) => (this.#head + HISTORY - frames) % HISTORY;
    if (this.#frames === 1) {
      return { prev: this.#head, cur: this.#head, next: this.#head };
    } else if (flush) {
      return { prev: back(1), cur: this.#head, next: this.#head };
    } else if (this.#frames === 2) {
      return { prev: back(1), cur: back(1), next: this.#head };
    } else {
      return { prev: back(2), cur: back(1), next: this.#head };
    }
  }

  /**
   * Put the canvas exactly where the element's picture is.
   *
   * The buffer holds coded pixels and is stretched across a box of the shape
   * the picture is meant to be seen in, which is what applies the sample
   * aspect ratio -- the same stretch the element does with its own picture.
   * The box itself is the picture's, not the element's: a media element fits
   * its picture inside its box and this has to land on top of that, so the fit
   * is worked out again here. It assumes the element's `object-fit` is the
   * `contain` it is by default.
   */
  #layout(): void {
    // Being laid out again is the other thing that survives an adoption: the
    // element arrives in a box of a different shape, and the observer that
    // reports it is the one already watching for that.
    this.#followOwner();
    if (!this.#wrapper) return;
    const video = this.#video;
    // The size the picture is to be seen at, sample aspect ratio and all.
    const displayWidth = this.#decoded ? this.#displayWidth : video.videoWidth;
    const displayHeight = this.#decoded
      ? this.#displayHeight
      : video.videoHeight;
    if (displayWidth === 0 || displayHeight === 0) return;
    const scale = Math.min(
      video.offsetWidth / displayWidth,
      video.offsetHeight / displayHeight,
    );
    const width = displayWidth * scale;
    const height = displayHeight * scale;
    this.#displayCanvas.style.left = `${video.offsetLeft + (video.offsetWidth - width) / 2}px`;
    this.#displayCanvas.style.top = `${video.offsetTop + (video.offsetHeight - height) / 2}px`;
    this.#displayCanvas.style.width = `${width}px`;
    this.#displayCanvas.style.height = `${height}px`;
  }

  #resize(width: number, height: number): void {
    const gl = this.#gl;
    this.#renderCanvas.width = width;
    this.#renderCanvas.height = height;
    this.#width = width;
    this.#height = height;
    this.#frames = 0;
    this.#filmHold = 0;
    this.#presentedPicture = null;
    this.#dropQueue();
    this.#layout();
    for (const texture of this.#textures) gl.deleteTexture(texture);
    this.#textures = [];
    for (let index = 0; index < HISTORY; index++) {
      const texture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, texture);
      // Every read is a texelFetch at an integer coordinate, so there is
      // nothing for a filter or a mipmap to do.
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      // Sized here so every ring slot is a complete texture before the first
      // frame. #push then uploads with texImage2D, or swaps in a texture that
      // already holds the picture.
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        width,
        height,
        0,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        null,
      );
      this.#textures.push(texture);
    }
    this.#freeOutputs();
    if (this.#doubleRate || this.#film || this.#decoded)
      this.#allocateOutputs();
    this.#converter?.resize(width, height);
    this.#detector?.resize(width, height);
    // Fresh resources mean fresh attempts: a degraded engine retries on the
    // next frame instead of staying stood down for the stream's lifetime.
    this.#recoverFilm();
  }

  /**
   * Somewhere to keep a filtered field until its moment comes.
   *
   * A frame's worth of texture each, so they exist only while a picture is
   * being shown for every field. Where a framebuffer will not take one -- an
   * implementation that will not render to RGBA8, or memory it will not find
   * -- the whole lot goes and the fields are drawn as their frames arrive,
   * which is the timing this replaces but is still a picture.
   */
  #allocateOutputs(): void {
    const gl = this.#gl;
    if (this.#outputs.length === OUTPUT_POOL_LENGTH || this.#width === 0)
      return;
    this.#freeOutputs();
    for (let index = 0; index < OUTPUT_POOL_LENGTH; index++) {
      const texture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        this.#width,
        this.#height,
        0,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        null,
      );
      const framebuffer = gl.createFramebuffer();
      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
      gl.framebufferTexture2D(
        gl.FRAMEBUFFER,
        gl.COLOR_ATTACHMENT0,
        gl.TEXTURE_2D,
        texture,
        0,
      );
      const complete =
        gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      if (!complete) {
        gl.deleteFramebuffer(framebuffer);
        gl.deleteTexture(texture);
        this.#freeOutputs();
        return;
      }
      this.#outputs.push({ texture, framebuffer });
    }
    this.#outputHead = OUTPUT_POOL_LENGTH - 1;
  }

  #freeOutputs(): void {
    const gl = this.#gl;
    const shownTexture =
      this.#presentedPicture?.kind === "texture"
        ? this.#presentedPicture.texture
        : null;
    // Direct draws and history textures remain reproducible when this pool is
    // released. Do not leave a snapshot pointing at a deleted output texture.
    if (this.#outputs.some((output) => output.texture === shownTexture))
      this.#presentedPicture = null;
    this.#shownOutput = null;
    this.#shownStart = null;
    this.#previousStart = null;
    for (const { texture, framebuffer } of this.#outputs) {
      gl.deleteFramebuffer(framebuffer);
      gl.deleteTexture(texture);
    }
    this.#outputs = [];
    this.#dropQueue();
  }

  /**
   * Wrap the element in a `<div>` of this one's own and put the canvas over
   * it. The wrapper is what the canvas is positioned against; moving the
   * element out of the tree and back within the one task leaves playback
   * alone, which is what makes turning this on mid-stream free.
   */
  #mount(): void {
    if (this.#wrapper) return;
    const parent = this.#video.parentElement;
    if (!parent) return;
    const wrapper = document.createElement("div");
    wrapper.style.cssText =
      "position:relative;display:inline-block;line-height:0;max-width:100%";
    parent.insertBefore(wrapper, this.#video);
    wrapper.appendChild(this.#video);
    wrapper.appendChild(this.#displayCanvas);
    this.#wrapper = wrapper;
    this.#resizes?.observe(this.#video);
    this.#layout();
  }

  #unmount(): void {
    if (this.#externalHost) return;
    const wrapper = this.#wrapper;
    this.#wrapper = null;
    this.#resizes?.disconnect();
    this.#displayCanvas.remove();
    if (!wrapper?.parentElement) return;
    wrapper.parentElement.insertBefore(this.#video, wrapper);
    wrapper.remove();
  }

  #onResize = (): void => this.#layout();

  /** Forward a media event with the page's playback state that gives it meaning. */
  #postWorkerEvent(
    name:
      | "emptied"
      | "pause"
      | "ended"
      | "seeking"
      | "seeked"
      | "ratechange"
      | "waiting",
  ): boolean {
    if (!this.#worker || this.#workerState === "main") return false;
    this.#worker.postMessage({
      type: "event",
      name,
      video: this.#workerVideoState(),
    } satisfies WorkerCommand);
    return true;
  }

  #onEmptied = (): void => {
    if (this.#decoded) {
      this.#clock.hold();
      this.#postWorkerEvent("emptied");
      return;
    }
    if (this.#postWorkerEvent("emptied")) {
      this.#closePendingWorkerFrame();
      this.#setVisible(false);
      return;
    }
    this.#frames = 0;
    this.#lastMediaTime = 0;
    this.#lastPresentedFrames = 0;
    this.#dropQueue();
    this.#resetFieldMetrics();
    this.#filmHold = 0;
    this.#periodMs = 0;
    // The counts belong to the stream that has just gone; the next one starts
    // its own. The element resets its own dropped count for the same reason.
    this.#resetStats();
    this.#presentedPicture = null;
    this.#setVisible(false);
  };

  #resetStats(): void {
    this.#stats = {
      filtered: 0,
      missed: 0,
      degraded: 0,
      discontinuities: 0,
      resynced: 0,
      late: 0,
      queueResetted: 0,
      matched: 0,
    };
    this.#picturesPushed = 0;
    this.#workerPictureDrops = 0;
    this.#phaseCounts.fill(0);
    this.#filmDropped = 0;
    this.#lastPresented = 0;
    this.#reportedAt = 0;
    this.#lastFrameAt = 0;
    this.#renderFramesSinceReport = 0;
    this.#renderMsSinceReport = 0;
    this.#showFramesSinceReport = 0;
    this.#showMsSinceReport = 0;
    this.#reportMaxQueuedFields = 0;
    this.#outputSinceReport = 0;
    this.#dropQueue();
    this.#gpuFrameNanosecondsSinceReport = 0;
    this.#gpuFrameCountSinceReport = 0;
    this.#gpuFieldNanosecondsSinceReport = 0;
    this.#gpuFieldCountSinceReport = 0;
  }

  /**
   * A new seek invalidates any destination frame remembered for the last one.
   */
  #onSeeking = (): void => {
    if (this.#decoded) {
      this.#clock.hold();
      this.#postWorkerEvent("seeking");
      return;
    }
    if (this.#postWorkerEvent("seeking")) {
      this.#closePendingWorkerFrame();
      return;
    }
    this.#seekFrameReady = false;
  };

  /**
   * Playback stopped, so the frame being held back goes up now. One picture,
   * whatever the rate: a still frame stands for a moment, and the moment is
   * the one the first field was taken at.
   */
  #onFlush = (event: Event): void => {
    // Decoded pictures are shown by the clock, which only has to start again.
    if (this.#decoded) {
      this.#clock.hold();
      this.#postWorkerEvent(
        event.type as "pause" | "ended" | "seeked" | "ratechange",
      );
      return;
    }
    if (event.type === "ratechange") {
      if (this.#videoFrames.captureDriven) this.#startCaptureLoop();
      else this.#stopCaptureLoop();
    }
    if (
      (event.type === "pause" ||
        event.type === "ended" ||
        event.type === "seeked" ||
        event.type === "ratechange") &&
      this.#postWorkerEvent(event.type)
    ) {
      this.#closePendingWorkerFrame();
      return;
    }
    if (event.type === "seeked") {
      // A destination frame may have reached requestVideoFrameCallback() while
      // the element still reported `seeking`. #onFrame has already discarded
      // the old history and drawn that frame, so clearing it here would turn a
      // completed seek back into a blank canvas until another frame arrives.
      const seekFrameReady = this.#seekFrameReady;
      this.#seekFrameReady = false;
      if (seekFrameReady) return;
      // A seek completes with the video on its destination frame. History still
      // belongs to the former position, so expose the video until the callback
      // refills every texture from the new timeline.
      this.#frames = 0;
      this.#dropQueue();
      this.#resetFieldMetrics();
      this.#presentedPicture = null;
      this.#setVisible(false);
      return;
    }
    const rateChanged = event.type === "ratechange";
    if (rateChanged) {
      // The measured wall-time period includes playback rate, so the next
      // callback establishes a fresh cadence from the new rate.
      this.#periodMs = 0;
      this.#lastMediaTime = this.#video.currentTime;
    }
    // The fields still queued stand for moments after this one and nothing is
    // coming to make sense of them, so the picture goes straight to the canvas
    // rather than through a schedule that has nothing left to keep to.
    this.#dropQueue();
    if (this.#running && this.#frames > 0) {
      const slot = this.#nextOutputSlot();
      const output = slot === null ? undefined : this.#outputs[slot];
      if (slot !== null && output) {
        // Keep the flushed picture in its own texture so capture can reproduce
        // it even though the next video frame will upload into history.
        this.#outputHead = slot;
        this.#render(true, false, output.framebuffer);
        this.#show(slot);
      } else {
        this.#render(true, false, null);
      }
    }
    if (rateChanged) {
      // Rebuild frame history and cadence for the new playback rate before reconstructing film.
      this.#frames = 0;
      this.#lastPresented = 0;
      this.#resetFieldMetrics();
    }
  };

  /** The element ran out of data. Its readings stop moving until it has more. */
  #onWaiting = (): void => {
    if (!this.#decoded) return;
    this.#clock.hold();
    this.#postWorkerEvent("waiting");
  };

  /**
   * A lost context takes the textures and the program with it. Rebuilding
   * them is possible, but a page that has lost its context has bigger
   * problems; getting out of the way leaves the element's own picture showing.
   */
  #onContextLost = (event: Event): void => {
    event.preventDefault();
    if (this.#externalHost) {
      this.#externalHost.onFailure("the deinterlacer WebGL context was lost");
      return;
    }
    if (this.#workerState === "active") return;
    this.#lost = true;
    this.#notifyFailure("the deinterlacer WebGL context was lost");
    this.stop();
  };
}

/** @internal Connect the shared rendering engine to an OffscreenCanvas in a Worker. */
export function createWorkerDeinterlacer(
  video: HTMLVideoElement,
  canvas: OffscreenCanvas,
  options: DeinterlacerOptions,
  onFailure: (message: string) => void,
  onVisibility: (visible: boolean) => void,
  requestAnimationFrame: (callback: FrameRequestCallback) => number,
  cancelAnimationFrame: (handle: number) => void,
): Deinterlacer {
  return new Deinterlacer(video, options, {
    canvas,
    onFailure,
    onVisibility,
    requestAnimationFrame,
    cancelAnimationFrame,
  });
}

function createProgram(
  gl: WebGL2RenderingContext,
  source: string,
): WebGLProgram {
  const program = gl.createProgram();
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX_SHADER);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, source);
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  // Attached shaders live as long as the program needs them, and it is the
  // program that holds them now.
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const log = gl.getProgramInfoLog(program);
    gl.deleteProgram(program);
    throw new Error(
      `the deinterlacer failed to link: ${log ?? "no reason given"}`,
    );
  }
  return program;
}

function compile(
  gl: WebGL2RenderingContext,
  kind: GLenum,
  source: string,
): WebGLShader {
  const shader = gl.createShader(kind);
  if (!shader) throw new Error("the deinterlacer could not create a shader");
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const log = gl.getShaderInfoLog(shader);
    gl.deleteShader(shader);
    throw new Error(
      `the deinterlacer failed to compile: ${log ?? "no reason given"}`,
    );
  }
  return shader;
}
